package com.hidegrounditems;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class HideGroundItemsPluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(HideGroundItemsPlugin.class);
		RuneLite.main(args);
	}
}

package com.hidegrounditems;

import java.awt.event.InputEvent;
import java.awt.event.KeyEvent;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Keybind;

@ConfigGroup("hide-ground-items")
public interface HideGroundItemsConfig extends Config
{
	String GROUP = "hide-ground-items";

	@ConfigItem(
		keyName = "hideRightClickMenuOption",
		name = "Hide Right-Click Menu Option",
		description = "Hide the plugin's Hide Ground Item option from ground-item menus"
	)
	default boolean hideRightClickMenuOption()
	{
		return false;
	}

	@ConfigItem(
		keyName = "groupItemsByName",
		name = "Group items with the same name",
		description = "Combine item variants with the same name in the Search and Hidden tabs"
	)
	default boolean groupItemsByName()
	{
		return true;
	}

	@ConfigItem(
		keyName = "removeHiddenItemsFromSearch",
		name = "Remove hidden items from search",
		description = "Hide already-hidden items from Search instead of showing an inline remove button"
	)
	default boolean removeHiddenItemsFromSearch()
	{
		return true;
	}

	@ConfigItem(
		keyName = "revealHiddenItemsHotkey",
		name = "Reveal hidden items hotkey",
		description = "Show all ground items and list controls while held"
	)
	default Keybind revealHiddenItemsHotkey()
	{
		return new Keybind(KeyEvent.VK_Z, InputEvent.CTRL_DOWN_MASK | InputEvent.SHIFT_DOWN_MASK);
	}

}

