	private void createProfileDraft()
	{
		if (!plugin.isRuneScapeProfileAvailable())
		{
			profileMessage.setForeground(ColorScheme.PROGRESS_ERROR_COLOR);
			profileMessage.setText("Log in to create profiles.");
			return;
		}

		String profileName = profileNameField.getText().trim();
		if (profileName.isEmpty())
		{
			profileMessage.setForeground(ColorScheme.PROGRESS_ERROR_COLOR);
			profileMessage.setText("Enter a profile name first.");
			return;
		}

		if (!plugin.beginNewProfileEdit(profileName))
		{
			profileMessage.setForeground(ColorScheme.PROGRESS_ERROR_COLOR);
			profileMessage.setText(plugin.profileNameExists(profileName)
				? "A profile with this name already exists."
				: "Profile name is invalid");
			return;
		}

		profileMessage.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		profileNameField.setText("");
		profileCreateForm.setVisible(false);
		setActionButtonSymbol(profileCreateToggle, "+");
		profileTop.revalidate();
		profileTop.repaint();
		editingProfileName = null;
		moveGlobalItemsOnSave = false;
		profileTop.setVisible(false);
		profileEditNameField.setText(profileName);
		profileEditRegionField.setText("");
		profileSearchField.setText("");
		showPopularItems();
		refreshProfileItems();
		((java.awt.CardLayout) profileViews.getLayout()).show(profileViews, "editor");
		profileEditor.setVisible(true);
		profileList.setVisible(false);
		updateTabAvailability();
		refreshBoundaryControls();
		profileEditNameField.requestFocusInWindow();
		profileEditNameField.selectAll();
	}

	private void importProfile()
	{
		if (!plugin.isRuneScapeProfileAvailable())
		{
			profileMessage.setText("Log in to import profiles.");
			return;
		}

		String json = readClipboardText();
		if (json == null || json.trim().isEmpty())
		{
			profileMessage.setText("The clipboard does not contain profile JSON.");
			return;
		}

		HideGroundItemsPlugin.ProfileImportResult result = plugin.importProfileJson(json);
		if (result.existing)
		{
			int overwrite = JOptionPane.showConfirmDialog(
				this,
				"A profile named \"" + result.profileName + "\" already exists. Overwrite it?",
				"Overwrite profile",
				JOptionPane.YES_NO_OPTION,
				JOptionPane.WARNING_MESSAGE);
			if (overwrite == JOptionPane.YES_OPTION)
			{
				result = plugin.importProfileJson(json, true);
			}
		}

		profileMessage.setText(result.message);
		if (!result.imported && !result.existing)
		{
			JOptionPane.showMessageDialog(this, result.message, "Import profile", JOptionPane.ERROR_MESSAGE);
		}
		refreshProfiles();
	}

	private String readClipboardText()
	{
		try
		{
			Transferable contents = Toolkit.getDefaultToolkit().getSystemClipboard().getContents(null);
			if (contents == null || !contents.isDataFlavorSupported(DataFlavor.stringFlavor))
			{
				return null;
			}
			return (String) contents.getTransferData(DataFlavor.stringFlavor);
		}
		catch (HeadlessException | IllegalStateException | java.awt.datatransfer.UnsupportedFlavorException | java.io.IOException ex)
		{
			profileMessage.setText("Unable to read profile JSON from the clipboard.");
			return null;
		}
	}

	private void refreshProfiles()
	{
		if (!SwingUtilities.isEventDispatchThread())
		{
			SwingUtilities.invokeLater(this::refreshProfiles);
			return;
		}

		profileList.removeAll();
		List<String> profileNames = plugin.getSavedProfileNames();
		for (String profileName : profileNames)
		{
			JPanel row = new JPanel(new BorderLayout(4, 0));
			row.setBackground(PANEL_BACKGROUND);
			row.setBorder(new EmptyBorder(2, 2, 2, 2));
			JLabel name = new JLabel(profileName);
			name.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
			name.setFont(name.getFont().deriveFont(Font.BOLD, 13f));
			List<Integer> regionIds = plugin.getSavedProfileRegions(profileName);
			String boundarySummary = plugin.getSavedProfileBoundarySummary(profileName);
			boolean hasRegions = !regionIds.isEmpty();
			boolean hasBoundaries = !boundarySummary.isEmpty();
			Color scopeColor = hasRegions || hasBoundaries
				? SCOPED_PROFILE_SCOPE : GLOBAL_PROFILE_SCOPE;
			String scopeTooltip = hasBoundaries
				? "Boundary profile: " + boundarySummary
				: hasRegions ? "Region profile: Region IDs " + regionIds
				: "Global profile: applies everywhere";
			name.setBorder(BorderFactory.createMatteBorder(0, 0, 2, 0, scopeColor));
			if (!regionIds.isEmpty() || !boundarySummary.isEmpty())
			{
				name.setToolTipText((regionIds.isEmpty() ? "" : "Region IDs: " + regionIds)
					+ (boundarySummary.isEmpty() ? "" : (regionIds.isEmpty() ? "" : "; ") + boundarySummary));
			}
			else
			{
				name.setToolTipText(scopeTooltip);
			}
			row.add(name, BorderLayout.CENTER);

			JPanel actions = new JPanel(new java.awt.FlowLayout(java.awt.FlowLayout.RIGHT, 3, 0));
			actions.setBackground(PANEL_BACKGROUND);
			JToggleButton active = new RuneLiteToggle();
			active.setSelected(plugin.isProfileActive(profileName));
			active.setToolTipText("Activate this profile");
			active.addActionListener(e ->
			{
				plugin.setProfileActive(profileName, active.isSelected());
				profileMessage.setText("");
				refreshProfiles();
			});
			actions.add(active);
			JButton edit = new JButton("Edit");
			setSearchButtonSize(edit, 42);
			setBoldButtonFont(edit);
			edit.setToolTipText("Edit this profile");
			edit.addActionListener(e -> beginEditedProfile(profileName));
			actions.add(edit);
			JButton export = new JButton("Copy");
			setSearchButtonSize(export, 44);
			setBoldButtonFont(export);
			export.setToolTipText("Copy this profile as portable JSON");
			export.addActionListener(e -> copyProfileJson(profileName));
			actions.add(export);
			JButton delete = new JButton("-");
			setActionButtonSize(delete);
			delete.setForeground(ColorScheme.PROGRESS_ERROR_COLOR);
			delete.setToolTipText("Delete this profile");
			delete.addActionListener(e ->
			{
				int choice = JOptionPane.showConfirmDialog(
					this,
					"Delete the saved profile \"" + profileName + "\"?",
					"Delete profile",
					JOptionPane.YES_NO_OPTION,
					JOptionPane.WARNING_MESSAGE);
				if (choice != JOptionPane.YES_OPTION)
				{
					return;
				}

				plugin.deleteProfile(profileName);
				profileMessage.setText("");
				refreshProfiles();
			});
			actions.add(delete);
			row.add(actions, BorderLayout.EAST);
			setFixedRowSize(row);
			profileList.add(row);
		}

		if (profileNames.isEmpty())
		{
			profileMessage.setText(plugin.isRuneScapeProfileAvailable()
				? ""
				: "Log in to load your profiles.");
		}
		else if ("Log in to load your profiles.".equals(profileMessage.getText()))
		{
			// The panel can be opened before login. Clear the pre-login message once
			// the saved profiles for the logged-in RuneScape account are available.
			profileMessage.setText("");
		}
		profileList.revalidate();
		profileList.repaint();
	}

	private void copyProfileJson(String profileName)
	{
		try
		{
			Toolkit.getDefaultToolkit().getSystemClipboard().setContents(
				new StringSelection(plugin.exportProfileJson(profileName)), null);
			profileMessage.setText("Copied JSON for " + profileName);
		}
		catch (HeadlessException | IllegalStateException ex)
		{
			profileMessage.setText("Unable to copy profile JSON to the clipboard.");
		}
	}

	private void beginEditedProfile(String profileName)
	{
		if (!plugin.isRuneScapeProfileAvailable())
		{
			profileMessage.setText("Log in to edit profiles.");
			return;
		}

		editingProfileName = profileName;
		moveGlobalItemsOnSave = false;
