	void scheduleProfileAutoSave()
	{
		if (!SwingUtilities.isEventDispatchThread())
		{
			SwingUtilities.invokeLater(this::scheduleProfileAutoSave);
			return;
		}

		if (plugin.isProfileEditing())
		{
			profileAutoSaveTimer.restart();
		}
	}

	private boolean autoSaveEditedProfile()
	{
		if (!plugin.isProfileEditing() || plugin.isBoundarySelectionActive())
		{
			return false;
		}

		String newProfileName = profileEditNameField.getText().trim();
		if (newProfileName.isEmpty())
		{
			profileEditMessage.setText("Enter a profile name.");
			return false;
		}

		String savedProfileName = plugin.autoSaveProfileEdit(
			editingProfileName, newProfileName, parseRegionIds(profileEditRegionField.getText()));
		if (savedProfileName == null)
		{
			profileEditMessage.setText("A profile with this name already exists or is invalid.");
			return false;
		}

		editingProfileName = savedProfileName;
		profileEditMessage.setText("");
		if (moveGlobalItemsOnSave)
		{
			plugin.clearGlobalHiddenItems();
			moveGlobalItemsOnSave = false;
		}
		return true;
	}

	private void finishEditedProfile()
	{
		if (!plugin.isProfileEditing())
		{
			return;
		}

		if (plugin.isBoundarySelectionActive())
		{
			plugin.finishBoundarySelection();
		}
		profileAutoSaveTimer.stop();
		if (!autoSaveEditedProfile())
		{
			return;
		}

		plugin.endProfileEdit();
		editingProfileName = null;
		profileCreateForm.setVisible(false);
		setActionButtonSymbol(profileCreateToggle, "+");
		profileTop.setVisible(true);
		profileEditor.setVisible(false);
		profileList.setVisible(true);
		((java.awt.CardLayout) profileViews.getLayout()).show(profileViews, "list");
		updateTabAvailability();
		refreshBoundaryControls();
		refreshProfiles();
	}

	private void confirmMoveGlobalHiddenItems()
	{
		if (!plugin.isProfileEditing())
		{
			return;
		}

		String profileName = profileEditNameField.getText().trim();

		Set<Integer> globalItemIds = plugin.getGlobalHiddenItemIds();
		if (globalItemIds.isEmpty())
		{
			profileMessage.setText("The global Hidden items list is empty.");
			return;
		}

		JPanel iconGrid = createHiddenItemIconGrid(globalItemIds);
		int itemCount = iconGrid.getComponentCount();
		JPanel confirmation = new JPanel(new BorderLayout(0, 8));
		confirmation.setBackground(PANEL_BACKGROUND);
		JLabel confirmationText = new JLabel("<html>Move all " + itemCount
			+ " global Hidden item" + (itemCount == 1 ? "" : "s") + " into \"" + escape(profileName)
			+ "\"?<br><br>The profile will be saved automatically and the global Hidden items list will be cleared.</html>");
		confirmationText.setFont(confirmationText.getFont().deriveFont(Font.PLAIN, 14f));
		confirmationText.setBorder(new EmptyBorder(2, 2, 2, 2));
		confirmation.add(confirmationText, BorderLayout.NORTH);
		int iconRows = Math.max(1, (iconGrid.getComponentCount() + 5) / 6);
		JScrollPane iconScroll = new JScrollPane(iconGrid,
			ScrollPaneConstants.VERTICAL_SCROLLBAR_AS_NEEDED,
			ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);
		iconScroll.setPreferredSize(new Dimension(300, Math.min(240,
			Math.max(48, iconRows * 42 + 8))));
		confirmation.add(iconScroll, BorderLayout.CENTER);
		int choice = JOptionPane.showConfirmDialog(
			this,
			confirmation,
			"Move Hidden items to profile",
			JOptionPane.YES_NO_OPTION,
			JOptionPane.WARNING_MESSAGE);
		if (choice != JOptionPane.YES_OPTION)
		{
			return;
		}

		plugin.replaceProfileDraftWithGlobalHiddenItems();
		moveGlobalItemsOnSave = true;
		autoSaveEditedProfile();
	}

	private JPanel createHiddenItemIconGrid(java.util.Set<Integer> itemIds)
	{
		List<Integer> sortedIds = new ArrayList<>(itemIds);
		sortedIds.sort(Integer::compareTo);
		Map<String, List<Integer>> groupedIds = new LinkedHashMap<>();
		for (int itemId : sortedIds)
		{
			String key = plugin.isGroupItemsByName()
				? normalizeItemName(plugin.getItemName(itemId))
				: String.valueOf(itemId);
			groupedIds.computeIfAbsent(key, ignored -> new ArrayList<>()).add(itemId);
		}

		JPanel iconGrid = new JPanel(new java.awt.GridLayout(0, 6, 4, 4));
		iconGrid.setBackground(PANEL_BACKGROUND);
		for (List<Integer> groupIds : groupedIds.values())
		{
			int itemId = groupIds.get(0);
			JPanel cell = new JPanel(new BorderLayout());
			cell.setBackground(PANEL_BACKGROUND);
			cell.setPreferredSize(new Dimension(40, 36));
			JLabel icon = new JLabel();
			icon.setHorizontalAlignment(SwingConstants.CENTER);
			icon.setPreferredSize(new Dimension(36, 36));
			String itemName = plugin.getItemName(itemId);
			icon.setToolTipText(itemName + " (IDs: " + formatIds(groupIds) + ")");
			net.runelite.client.util.AsyncBufferedImage image = itemManager.getImage(itemId);
			if (image != null)
			{
				image.addTo(icon);
			}
			cell.add(icon, BorderLayout.CENTER);
			iconGrid.add(cell);
		}
		return iconGrid;
	}

	private void refreshBoundaryControls()
	{
		boolean editing = plugin.isProfileEditing();
		boolean loggedIn = plugin.isGameLoggedIn();
		boolean selecting = plugin.isBoundarySelectionActive();
		boolean polygon = plugin.isBoundaryPolygonMode();
		drawTiles.setText(selecting && !polygon ? "Finish" : "Tiles");
		drawPolygon.setText(selecting && polygon ? "Finish" : "Polygons");
		drawTiles.setToolTipText(selecting && !polygon
			? "Finish tile selection (Enter also finishes)"
			: "Draw or toggle individual tiles and rectangles");
		drawPolygon.setToolTipText(selecting && polygon
			? "Finish polygon selection (Enter also finishes)"
			: "Draw a boundary by clicking polygon vertices");
		drawTiles.setEnabled(editing && loggedIn && (!selecting || !polygon));
		drawPolygon.setEnabled(editing && loggedIn && (!selecting || polygon));
		clearBoundary.setEnabled(editing && loggedIn && !plugin.isBoundarySelectionActive());
		if (!loggedIn && editing)
		{
			drawTiles.setToolTipText("Log in to draw tile boundaries");
			drawPolygon.setToolTipText("Log in to draw polygon boundaries");
			clearBoundary.setToolTipText("Log in to clear tile boundaries");
		}
	}

	private void updateTabAvailability()
	{
		if (tabs.getTabCount() < 3)
		{
			return;
		}

		boolean editing = plugin.isProfileEditing();
		tabs.setEnabledAt(0, !editing);
		tabs.setEnabledAt(1, !editing);
		tabs.setEnabledAt(2, true);
		String tooltip = editing ? "Finish or cancel profile editing first" : null;
		tabs.setToolTipTextAt(0, tooltip);
		tabs.setToolTipTextAt(1, tooltip);
	}

