	private void refreshProfileItems()
	{
		profileItemList.removeAll();
		List<Integer> ids = new ArrayList<>(plugin.getProfileDraftItemIds());
		ids.sort(Integer::compareTo);
		Map<String, List<Integer>> groupedIds = new LinkedHashMap<>();
		for (int itemId : ids)
		{
			String key = plugin.isGroupItemsByName()
				? normalizeItemName(plugin.getItemName(itemId))
				: String.valueOf(itemId);
			groupedIds.computeIfAbsent(key, ignored -> new ArrayList<>()).add(itemId);
		}

		for (List<Integer> itemIds : groupedIds.values())
		{
			JPanel row = new JPanel(new BorderLayout(4, 0));
			row.setBackground(PANEL_BACKGROUND);
			row.setBorder(new EmptyBorder(2, 2, 2, 2));
			int representativeId = itemIds.get(0);
			JLabel icon = new JLabel();
			icon.setPreferredSize(new Dimension(36, 36));
			net.runelite.client.util.AsyncBufferedImage image = itemManager.getImage(representativeId);
			if (image != null)
			{
				image.addTo(icon);
			}
			row.add(createItemLabel(plugin.getItemName(representativeId), itemIds, 76), BorderLayout.CENTER);
			JButton remove = new JButton("-");
			setActionButtonSize(remove);
			remove.setForeground(ColorScheme.PROGRESS_ERROR_COLOR);
			remove.setToolTipText("Remove from profile");
			remove.addActionListener(e ->
			{
				plugin.removeSearchItems(itemIds);
				refreshProfileItems();
			});
			row.add(icon, BorderLayout.WEST);
			row.add(remove, BorderLayout.EAST);
			setFixedRowSize(row);
			profileItemList.add(row);
		}
		profileItemList.revalidate();
		profileItemList.repaint();
	}

	private static String joinIds(List<Integer> ids)
	{
		StringBuilder value = new StringBuilder();
		for (Integer id : ids)
		{
			if (value.length() > 0)
			{
				value.append(", ");
			}
			value.append(id);
		}
		return value.toString();
	}

	private JPanel createRegionInput(HintTextField field)
	{
		JPanel input = new JPanel(new BorderLayout(4, 0));
		input.setBackground(PANEL_BACKGROUND);
		JButton current = new JButton("+");
		setActionButtonSize(current);
		current.setForeground(ACTION_BLUE);
		setActionButtonSymbol(current, "↓");
		current.setToolTipText("Add the current packed Region ID");
		current.addActionListener(e -> addCurrentRegionId(field));
		input.add(field, BorderLayout.CENTER);
		input.add(current, BorderLayout.EAST);
		input.setAlignmentX(LEFT_ALIGNMENT);
		input.setMinimumSize(new Dimension(0, 24));
		input.setPreferredSize(new Dimension(0, 24));
		input.setMaximumSize(new Dimension(Integer.MAX_VALUE, 24));
		return input;
	}

	private void addCurrentRegionId(HintTextField field)
	{
		Integer regionId = plugin.getCurrentRegionId();
		if (regionId == null)
		{
			profileMessage.setText("Log in before adding the current Region ID.");
			return;
		}

		List<Integer> regionIds = parseRegionIds(field.getText());
		if (!regionIds.contains(regionId))
		{
			regionIds.add(regionId);
		}
		field.setText(joinIds(regionIds));
	}

	private void toggleBoundarySelection(boolean polygon)
	{
		if (plugin.isBoundarySelectionActive())
		{
			if (plugin.isBoundaryPolygonMode() == polygon)
			{
				plugin.finishBoundarySelection();
			}
			return;
		}

		if (!plugin.beginBoundarySelection(polygon))
		{
			profileMessage.setText("Log in and open a profile editor before selecting tiles.");
		}
		refreshBoundaryControls();
	}

