		{
			plugin.clearProfileBoundary();
		}
	}

	private static List<Integer> parseRegionIds(String value)
	{
		List<Integer> regionIds = new ArrayList<>();
		for (String part : value.split(","))
		{
			try
			{
				int regionId = Integer.parseInt(part.trim());
				if (regionId >= 0)
				{
					regionIds.add(regionId);
				}
			}
			catch (NumberFormatException ignored)
			{
				// Ignore incomplete or invalid region IDs while typing.
