	void refresh()
	{
		if (!SwingUtilities.isEventDispatchThread())
		{
			SwingUtilities.invokeLater(this::refresh);
			return;
		}

		updating = true;
		updateTabAvailability();
		refreshProfiles();
		refreshBoundaryControls();
		if (plugin.isProfileEditing())
		{
			refreshProfileItems();
		}
		hideAll.setSelected(plugin.isHideAll());
		hideListed.setSelected(plugin.isHideListedItems());
		hideGroundItemLabels.setSelected(plugin.isHideGroundItemLabels());
		hideGroundItemsPluginItems.setSelected(plugin.isHideGroundItemsPluginItems());
		showProfileHiddenItems.setSelected(plugin.isShowProfileHiddenItemsWhileEditing());
		List<String> overlaps = plugin.getGroundItemsOverlaps();
		if (plugin.isHideGroundItemLabels() && plugin.isGroundItemsPluginActive())
		{
			labelWarning.setText("Item labels from the Ground Items plugin are forcefully disabled.");
		}
		else if (!overlaps.isEmpty())
		{
			labelWarning.setText("Text from hidden items are still being displayed by the Ground Items plugin.");
		}
		labelWarning.setVisible((plugin.isHideGroundItemLabels() && plugin.isGroundItemsPluginActive())
			|| !overlaps.isEmpty());
		if (labelWarning.getParent() != null)
		{
			labelWarning.getParent().revalidate();
			labelWarning.getParent().repaint();
		}
		itemList.removeAll();

		// Profile items are controlled by the active profile toggle and its boundary;
		// only the user's global list belongs in this tab.
		List<Integer> ids = new ArrayList<>(plugin.getGlobalHiddenItemIds());
		java.util.Set<Integer> overlapIds = plugin.getGroundItemsOverlapIds();
		ids.sort(Integer::compareTo);
		Map<String, List<Integer>> groupedIds = new LinkedHashMap<>();
		for (int itemId : ids)
		{
			String key = plugin.isGroupItemsByName()
				? normalizeItemName(plugin.getItemName(itemId))
				: String.valueOf(itemId);
			groupedIds.computeIfAbsent(key, ignored -> new ArrayList<>()).add(itemId);
		}
		for (List<Integer> itemIds : groupedIds.values())
		{
			boolean groundItemsOverlap = itemIds.stream().anyMatch(overlapIds::contains);
			itemList.add(createItemRow(itemIds, groundItemsOverlap));
		}
		hiddenHeader.setVisible(!ids.isEmpty());
		itemList.setVisible(!ids.isEmpty());

		itemList.revalidate();
		itemList.repaint();
		hiddenBody.revalidate();
		hiddenBody.repaint();
		if (hiddenBody.getParent() != null)
		{
			hiddenBody.getParent().revalidate();
			hiddenBody.getParent().repaint();
		}
		if (itemList.getParent() != null)
		{
			itemList.getParent().revalidate();
			itemList.getParent().repaint();
			SwingUtilities.invokeLater(() ->
			{
				itemList.getParent().revalidate();
				itemList.getParent().repaint();
			});
		}
		updating = false;
		boolean groupingChanged = renderedGroupItemsByName == null
			|| renderedGroupItemsByName != plugin.isGroupItemsByName();
		renderedGroupItemsByName = plugin.isGroupItemsByName();
		if (groupingChanged && !itemField.getText().trim().isEmpty())
		{
			plugin.searchItems(itemField.getText());
		}
	}

	void showSearchResults(List<HideGroundItemsPlugin.ItemSearchResult> results)
	{
		if (!SwingUtilities.isEventDispatchThread())
		{
			SwingUtilities.invokeLater(() -> showSearchResults(results));
			return;
		}

		JPanel targetResults = plugin.isProfileEditing() ? profileSearchResults : searchResults;
		targetResults.removeAll();
		for (HideGroundItemsPlugin.ItemSearchResult result : results)
		{
			if (plugin.isRemoveHiddenItemsFromSearch()
				&& plugin.isGroupItemsByName()
				&& result.ids.stream().anyMatch(plugin::isSearchItemHidden))
			{
				continue;
			}

			List<Integer> visibleIds = new ArrayList<>();
			for (int itemId : result.ids)
			{
				if (!plugin.isRemoveHiddenItemsFromSearch() || !plugin.isSearchItemHidden(itemId))
				{
					visibleIds.add(itemId);
				}
			}
			if (visibleIds.isEmpty())
			{
				continue;
			}
			HideGroundItemsPlugin.ItemSearchResult visibleResult = visibleIds.size() == result.ids.size()
				? result
				: new HideGroundItemsPlugin.ItemSearchResult(result.name, visibleIds);

			JPanel row = new JPanel(new BorderLayout(4, 0));
			row.setBackground(PANEL_BACKGROUND);
			row.setBorder(new EmptyBorder(2, 2, 2, 2));

			JLabel icon = new JLabel();
			icon.setPreferredSize(new Dimension(36, 36));
			itemManager.getImage(visibleResult.id).addTo(icon);

			JLabel label = createItemLabel(visibleResult.name, visibleResult.ids,
				plugin.isProfileEditing() ? 76 : 92);
			row.add(label, BorderLayout.CENTER);

			boolean hidden = result.ids.stream().anyMatch(plugin::isSearchItemHidden);
			JButton action = new JButton(hidden ? "-" : "+");
			setActionButtonSize(action);
			action.setForeground(hidden ? ColorScheme.PROGRESS_ERROR_COLOR : ColorScheme.PROGRESS_COMPLETE_COLOR);
			action.setToolTipText(hidden ? "Remove hidden item" : "Add hidden item");
			action.addActionListener(e ->
			{
				if (hidden)
				{
					plugin.removeSearchItems(result.ids);
				}
				else
				{
					Set<Integer> globallyHidden = plugin.addSearchItems(visibleResult.ids);
					if (!globallyHidden.isEmpty())
					{
						profileEditMessage.setText(globallyHidden.size() == visibleResult.ids.size()
							? "This item is already in the global Hidden items list."
							: "Some items are already in the global Hidden items list and were skipped.");
					}
				}
				showSearchResults(results);
			});
			row.add(icon, BorderLayout.WEST);
			row.add(action, BorderLayout.EAST);
			setFixedRowSize(row);
			targetResults.add(row);
		}
		boolean hasResults = targetResults.getComponentCount() > 0;
		targetResults.setVisible(hasResults);
		targetResults.revalidate();
		targetResults.repaint();
		if (targetResults.getParent() != null)
		{
			targetResults.getParent().revalidate();
			targetResults.getParent().repaint();
		}
	}

