	private JPanel createItemRow(List<Integer> itemIds, boolean groundItemsOverlap)
	{
		JPanel row = new JPanel(new BorderLayout(4, 0));
		row.setBackground(PANEL_BACKGROUND);
		row.setBorder(new EmptyBorder(2, 2, 2, 2));
		if (groundItemsOverlap)
		{
			row.setToolTipText("Also highlighted by the Ground Items plugin");
		}

		int representativeId = itemIds.get(0);
		JLabel label = createItemLabel(plugin.getItemName(representativeId), itemIds);
		JLabel icon = new JLabel();
		icon.setPreferredSize(new Dimension(36, 36));
		if (groundItemsOverlap)
		{
			icon.setBorder(BorderFactory.createLineBorder(ColorScheme.PROGRESS_ERROR_COLOR, 2));
		}
		net.runelite.client.util.AsyncBufferedImage image = itemManager.getImage(representativeId);
		if (image != null)
		{
			image.addTo(icon);
		}
		row.add(icon, BorderLayout.WEST);
		row.add(label, BorderLayout.CENTER);

		JButton remove = new JButton("-");
		setActionButtonSize(remove);
		remove.setForeground(ColorScheme.PROGRESS_ERROR_COLOR);
		remove.setToolTipText("Remove hidden item group");
		remove.addActionListener(e ->
		{
			plugin.removeHiddenItems(itemIds);
			refreshSearchResults();
		});
		row.add(remove, BorderLayout.EAST);
		setFixedRowSize(row);
		return row;
	}

	private void searchOrAddItem()
	{
		String value = itemField.getText().trim();
		if (value.isEmpty())
		{
