		plugin.searchItems(value);
	}

	private void searchAsYouType()
	{
		String value = itemField.getText().trim();
		if (value.isEmpty())
		{
			showPopularItems();
		}
		else
		{
			try
			{
				Integer.parseInt(value);
				showSearchResults(Collections.emptyList());
				return;
			}
			catch (NumberFormatException ignored)
			{
				plugin.searchItems(value);
			}
		}
	}

	void refreshSearchResults()
	{
		if (!SwingUtilities.isEventDispatchThread())
		{
			SwingUtilities.invokeLater(this::refreshSearchResults);
			return;
		}

		String query = itemField.getText().trim();
		if (!query.isEmpty())
