	private void onSearchTextChanged()
	{
		searchTimer.restart();
		if (itemField.getText().trim().isEmpty())
		{
			searchTimer.stop();
			showPopularItems();
		}
	}

	void clearSearch()
	{
		if (!SwingUtilities.isEventDispatchThread())
		{
			SwingUtilities.invokeLater(this::clearSearch);
			return;
		}

		searchTimer.stop();
		itemField.setText("");
		showPopularItems();
		itemField.requestFocusInWindow();
	}

	private void showPopularItems()
	{
		List<HideGroundItemsPlugin.ItemSearchResult> results = new ArrayList<>();
		boolean namesMissing = false;
		for (int itemId : POPULAR_ITEM_IDS)
		{
			String name = plugin.getItemName(itemId);
			if ("Unknown item".equals(name))
			{
				namesMissing = true;
			}
			results.add(new HideGroundItemsPlugin.ItemSearchResult(name, Collections.singletonList(itemId)));
		}
		if (namesMissing)
		{
			plugin.resolveItemNames(POPULAR_ITEM_IDS);
		}
		showSearchResults(results);
	}

	void refreshPopularSearchResults()
	{
		if (!SwingUtilities.isEventDispatchThread())
		{
			SwingUtilities.invokeLater(this::refreshPopularSearchResults);
			return;
		}

		if ((plugin.isProfileEditing() && profileSearchField.getText().trim().isEmpty())
			|| (!plugin.isProfileEditing() && itemField.getText().trim().isEmpty()))
		{
			showPopularItems();
		}
	}

