	private static final class SymbolIcon implements javax.swing.Icon
	{
		private final String symbol;

		private SymbolIcon(String symbol)
		{
			this.symbol = symbol;
		}

		@Override
		public void paintIcon(java.awt.Component component, Graphics graphics, int x, int y)
		{
			Graphics2D graphics2D = (Graphics2D) graphics.create();
			graphics2D.setColor(component.getForeground());
			graphics2D.setStroke(new java.awt.BasicStroke(2f, java.awt.BasicStroke.CAP_ROUND,
				java.awt.BasicStroke.JOIN_ROUND));
			int centerX = x + getIconWidth() / 2;
			int centerY = y + getIconHeight() / 2;
			if ("+".equals(symbol))
			{
				graphics2D.drawLine(centerX - 5, centerY, centerX + 5, centerY);
				graphics2D.drawLine(centerX, centerY - 5, centerX, centerY + 5);
			}
			else if ("-".equals(symbol))
			{
				graphics2D.drawLine(centerX - 5, centerY, centerX + 5, centerY);
			}
			else
			{
				graphics2D.drawLine(centerX, y + 2, centerX, y + 9);
				graphics2D.drawLine(centerX, y + 9, centerX - 4, y + 5);
				graphics2D.drawLine(centerX, y + 9, centerX + 4, y + 5);
			}
			graphics2D.dispose();
		}

		@Override
		public int getIconWidth()
		{
			return 12;
		}

		@Override
		public int getIconHeight()
		{
			return 12;
		}
	}

