	private static JLabel createItemLabel(String name, List<Integer> itemIds, int width)
	{
		JLabel label = new JLabel("<html><div style='width: " + width + "px'>" + escape(name) + "</div></html>");
		label.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		label.setFont(label.getFont().deriveFont(Font.BOLD, 13f));
		label.setToolTipText(name + " (IDs: " + formatIds(itemIds) + ")");
		label.setPreferredSize(new Dimension(width, 24));
		return label;
	}

	private static String normalizeItemName(String name)
	{
		String normalized = name == null ? "" : name.trim().toLowerCase();
		return normalized.endsWith(" (noted)")
			? normalized.substring(0, normalized.length() - " (noted)".length())
			: normalized;
	}

	private static String formatIds(List<Integer> itemIds)
	{
		List<Integer> sortedIds = new ArrayList<>(itemIds);
		Collections.sort(sortedIds);
		StringBuilder formatted = new StringBuilder();
		int start = 0;
		while (start < sortedIds.size())
		{
			int end = start;
			while (end + 1 < sortedIds.size() && sortedIds.get(end + 1) == sortedIds.get(end) + 1)
			{
				end++;
			}

			if (formatted.length() > 0)
			{
				formatted.append(", ");
			}
			formatted.append(sortedIds.get(start));
			if (end > start)
			{
				formatted.append('-').append(sortedIds.get(end));
			}
			start = end + 1;
		}
		return formatted.toString();
	}

