		public void hotkeyReleased()
		{
			revealHiddenItemsHotkeyPressed = false;
			clearRevealItemHitboxes();
		}
	};

	private final MouseAdapter revealHiddenItemsMouseListener = new MouseAdapter()
	{
		@Override
		public MouseEvent mousePressed(MouseEvent event)
		{
			if (!revealHiddenItemsHotkeyPressed || !isCanvasEvent(event)
				|| !isLeftButtonEvent(event))
			{
				return event;
			}

			RevealItemHitbox hitbox = findRevealItemHitbox(event.getPoint());
			if (hitbox == null)
			{
				return event;
			}

			event.consume();
			clientThread.invoke(() ->
			{
				if (hitbox.remove)
				{
					removeHiddenItem(hitbox.itemId);
				}
				else
				{
					addHiddenItem(hitbox.itemId);
				}
				panel.refreshSearchResults();
				clearRevealItemHitboxes();
			});
			return event;
		}
	};

	private final MouseAdapter boundaryMouseListener = new MouseAdapter()
	{
		@Override
		public MouseEvent mousePressed(MouseEvent event)
		{
			if (!boundarySelectionActive || !isCanvasEvent(event))
			{
				return event;
			}

			if (isLeftButtonEvent(event))
			{
				event.consume();
				Point point = event.getPoint();
				clientThread.invoke(() ->
				{
					if (!boundarySelectionActive)
					{
						return;
					}

					// Resolve the press against the actual canvas coordinates on the
					// client thread so scene state cannot be read concurrently with
					// the game renderer.
					updateHoveredBoundaryTile(point, true);
					handleBoundaryLeftClick(event);
				});
			}
			else
			{
				queueBoundaryHoverUpdate(event.getPoint());
			}
			return event;
		}

		@Override
		public MouseEvent mouseDragged(MouseEvent event)
		{
			if (boundarySelectionActive && isCanvasEvent(event))
			{
				queueBoundaryHoverUpdate(event.getPoint());
				if (isLeftButtonEvent(event))
				{
					// Keep a left-button drawing gesture from reaching RuneLite's
					// normal world/camera handling while the editor is active.
					event.consume();
				}
			}
			return event;
		}

		@Override
		public MouseEvent mouseReleased(MouseEvent event)
		{
			if (boundarySelectionActive && isCanvasEvent(event) && isLeftButtonEvent(event))
			{
				event.consume();
			}
			return event;
		}

		@Override
		public MouseEvent mouseClicked(MouseEvent event)
		{
			// MouseManager dispatches the completed click separately from press
			// and release. Consume it as well so the game cannot interpret a
			// polygon/tile point as Walk Here or another world action.
			if (boundarySelectionActive && isCanvasEvent(event) && isLeftButtonEvent(event))
			{
				event.consume();
			}
			return event;
		}

		@Override
		public MouseEvent mouseMoved(MouseEvent event)
		{
			if (boundarySelectionActive && isCanvasEvent(event))
			{
				queueBoundaryHoverUpdate(event.getPoint());
			}
			return event;
		}
	};

	private boolean isCanvasEvent(MouseEvent event)
	{
		return event != null && client.getCanvas() != null
			&& event.getComponent() == client.getCanvas();
	}

	private static boolean isLeftButtonEvent(MouseEvent event)
	{
		return event != null && (event.getButton() == MouseEvent.BUTTON1
			|| (event.getModifiersEx() & MouseEvent.BUTTON1_DOWN_MASK) != 0);
	}

	private void queueBoundaryHoverUpdate(Point mousePosition)
	{
		if (mousePosition == null)
		{
			return;
		}

		pendingBoundaryMousePosition = new Point(mousePosition);
		pendingBoundaryMouseSequence++;
		if (boundaryHoverUpdateQueued.compareAndSet(false, true))
		{
			clientThread.invokeLater(this::processBoundaryHoverUpdate);
		}
	}

	private void processBoundaryHoverUpdate()
	{
		long processedSequence = pendingBoundaryMouseSequence;
		Point mousePosition = pendingBoundaryMousePosition;
		if (boundarySelectionActive && mousePosition != null)
		{
			updateHoveredBoundaryTile(mousePosition, false);
		}

		boundaryHoverUpdateQueued.set(false);
		if (processedSequence != pendingBoundaryMouseSequence
			&& boundaryHoverUpdateQueued.compareAndSet(false, true))
		{
			clientThread.invokeLater(this::processBoundaryHoverUpdate);
		}
	}

	private final KeyListener boundaryKeyListener = new KeyListener()
	{
		@Override
		public void keyPressed(KeyEvent event)
		{
			if (!boundarySelectionActive)
			{
				return;
			}

			if (event.getKeyCode() == KeyEvent.VK_ESCAPE)
			{
				cancelBoundarySelection();
				event.consume();
			}
			else if (event.getKeyCode() == KeyEvent.VK_ENTER)
			{
				finishBoundarySelection();
				event.consume();
			}
		}

		@Override public void keyTyped(KeyEvent event) { }
		@Override public void keyReleased(KeyEvent event) { }

		@Override
		public void focusLost()
