	private final RenderCallback renderCallback = new RenderCallback()
	{
		@Override
		public boolean addEntity(Renderable renderable, boolean drawingUI)
		{
			return shouldDraw(renderable, drawingUI);
		}

		@Override
		public boolean drawObject(Scene scene, TileObject object)
		{
			if (!(object instanceof ItemLayer))
			{
				return true;
			}

			ItemLayer itemLayer = (ItemLayer) object;
			boolean hasHiddenItem = false;
			for (Renderable renderable : new Renderable[]{itemLayer.getBottom(), itemLayer.getMiddle(), itemLayer.getTop()})
			{
				if (renderable instanceof TileItem)
				{
					TileItem item = (TileItem) renderable;
					trackGroundItem(item, itemLayer);
					if (isHiddenForRender(item))
					{
						// The public render callback can only suppress the complete item layer.
						// Do not allow a hidden item to leak when it shares a tile with another item.
						hasHiddenItem = true;
					}
				}
			}
			return !hasHiddenItem;
		}
	};

	@Override
	protected void startUp() throws Exception
	{
		updateState();
		mouseManager.registerMouseListener(boundaryMouseListener);
		mouseManager.registerMouseListener(revealHiddenItemsMouseListener);
		keyManager.registerKeyListener(boundaryKeyListener);
		keyManager.registerKeyListener(revealHiddenItemsHotkeyListener);
		renderCallbackManager.register(renderCallback);
		overlayManager.add(modelOverlay);
		trackCurrentGroundItems();
		updateGroundItemLabels();

		navigationButton = NavigationButton.builder()
			.tooltip("Hide Ground Items")
			.icon(createIcon())
			.priority(5)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navigationButton);
	}

	@Override
	protected void shutDown() throws Exception
	{
		cancelBoundarySelection();
		mouseManager.unregisterMouseListener(boundaryMouseListener);
		mouseManager.unregisterMouseListener(revealHiddenItemsMouseListener);
		keyManager.unregisterKeyListener(boundaryKeyListener);
		keyManager.unregisterKeyListener(revealHiddenItemsHotkeyListener);
		renderCallbackManager.unregister(renderCallback);
		overlayManager.remove(modelOverlay);
		revealHiddenItemsHotkeyPressed = false;
		clearRevealItemHitboxes();
		trackedGroundItems.clear();
		itemsByLayer.clear();
		restoreGroundItemLabels(false);
		if (navigationButton != null)
		{
			clientToolbar.removeNavigation(navigationButton);
			navigationButton = null;
		}
		hiddenItemIdsLoaded = false;
		globalHiddenItemIds = Collections.emptySet();
		activeProfileNames = Collections.emptySet();
		activeProfileItemIds = Collections.emptySet();
		activeProfiles = Collections.emptyList();
		profileDraftBoundaryPreviewTiles = Collections.emptySet();
		savedProfilesLoaded = false;
		savedProfiles = Collections.emptyMap();
		savedProfileRegions = Collections.emptyMap();
		savedProfileBoundaries = Collections.emptyMap();
		pendingHiddenItemIds = null;
	}

	@Override
	public void resetConfiguration()
	{
		configManager.unsetConfiguration(HideGroundItemsConfig.GROUP, "hideAll");
		configManager.unsetConfiguration(HideGroundItemsConfig.GROUP, "hideListedItems");
		configManager.unsetConfiguration(HideGroundItemsConfig.GROUP, "hideGroundItemLabels");
		configManager.unsetConfiguration(HideGroundItemsConfig.GROUP, "showLabels");
		configManager.unsetConfiguration(HideGroundItemsConfig.GROUP, "hideGroundItemsPluginItems");
		// Write the intended defaults explicitly so the Config panel immediately reflects
		// the reset, including when the reset is performed before entering the game.
		configManager.setConfiguration(HideGroundItemsConfig.GROUP, "groupItemsByName", true);
		configManager.setConfiguration(HideGroundItemsConfig.GROUP, "removeHiddenItemsFromSearch", true);

		restoreGroundItemLabels(false);
		hideAll = false;
		hideListedItems = true;
		hideGroundItemLabels = false;
		hideGroundItemsPluginItems = false;
		groupItemsByName = true;
		removeHiddenItemsFromSearch = true;
		groundItemsPluginHiddenItemIds = Collections.emptySet();
		updateGroundItemLabels();
		panel.refresh();
	}

	@Subscribe
	public void onConfigChanged(net.runelite.client.events.ConfigChanged event)
	{
		if (event.getGroup().equals(HideGroundItemsConfig.GROUP)
			&& event.getKey().equals(HIDDEN_ITEM_IDS_CONFIG_KEY))
		{
			Set<Integer> pendingIds = pendingHiddenItemIds;
			if (pendingIds != null)
			{
				if (serializeHiddenItemIds(pendingIds).equals(event.getNewValue()))
				{
					pendingHiddenItemIds = null;
				}
				return;
			}

			updateState();
			panel.refresh();
		}
		else if (event.getGroup().equals(HideGroundItemsConfig.GROUP)
			&& (event.getKey().equals(SAVED_PROFILES_CONFIG_KEY)
				|| event.getKey().equals(SAVED_PROFILE_REGIONS_CONFIG_KEY)
				|| event.getKey().equals(SAVED_PROFILE_BOUNDARIES_CONFIG_KEY)))
		{
			savedProfilesLoaded = false;
			updateState();
			panel.refresh();
		}
		else if (event.getGroup().equals(HideGroundItemsConfig.GROUP)
			&& event.getKey().equals(ACTIVE_PROFILE_CONFIG_KEY))
		{
			// Profile definitions and the active-profile list are written as separate
			// queued config updates. Reload the active list when its own update arrives;
			// otherwise an earlier profile-definition event can leave the runtime cache
			// temporarily (or permanently) without the profile being edited.
			loadActiveProfile();
			panel.refresh();
		}
		else if (event.getGroup().equals(HideGroundItemsConfig.GROUP)
			|| event.getGroup().equals("grounditems"))
		{
			updateState();
			updateGroundItemLabels();
			panel.refresh();
			panel.refreshSearchResults();
		}
	}

	@Subscribe
	public void onRuneScapeProfileChanged(RuneScapeProfileChanged event)
	{
		pendingHiddenItemIds = null;
		hiddenItemIdsLoaded = false;
		savedProfilesLoaded = false;
