		activeProfileItemIds = Collections.emptySet();
		activeProfiles = Collections.emptyList();
		profileDraftItemIds = null;
		profileDraftIsNew = false;
		profileEditingName = null;
		showProfileHiddenItemsWhileEditing = true;
		profileEditing = false;
		profileDraftBoundary = null;
		profileDraftBoundaryPreviewTiles = Collections.emptySet();
		cancelBoundarySelection();
		updateState();
		panel.refresh();
	}

	@Subscribe
	public void onPluginChanged(PluginChanged event)
	{
		if (!(event.getPlugin() instanceof GroundItemsPlugin))
		{
			return;
		}

		if (!event.isLoaded())
		{
			restoreGroundItemLabels(false);
		}
		else
		{
			updateGroundItemLabels();
		}
		clientThread.invoke(this::refreshGroundItemsPluginHiddenItemIds);
		panel.refresh();
	}

	@Subscribe
	public void onItemSpawned(ItemSpawned event)
	{
		ItemLayer layer = event.getTile().getItemLayer();
		if (layer != null)
		{
			trackGroundItem(event.getItem(), layer);
		}
	}

	@Subscribe
	public void onItemDespawned(ItemDespawned event)
	{
		untrackGroundItem(event.getItem());
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGGED_IN)
		{
			// The Profiles panel may have been opened before login. Refresh it after
			// the RuneScape profile becomes available so its pre-login message does
			// not remain visible while the client is in-game.
			panel.refresh();
			clientThread.invoke(this::trackCurrentGroundItems);
		}
		else
		{
			revealHiddenItemsHotkeyPressed = false;
			clearRevealItemHitboxes();
			cancelBoundarySelection();
			trackedGroundItems.clear();
			itemsByLayer.clear();
			panel.refresh();
		}
	}

	private void trackCurrentGroundItems()
	{
		if (client.getScene() == null || client.getScene().getTiles() == null)
		{
			return;
		}

		for (net.runelite.api.Tile[][] plane : client.getScene().getTiles())
		{
			if (plane == null)
			{
				continue;
			}

			for (net.runelite.api.Tile[] column : plane)
			{
				if (column == null)
				{
					continue;
				}

				for (net.runelite.api.Tile tile : column)
				{
					if (tile == null || tile.getItemLayer() == null)
					{
						continue;
					}

					if (tile.getGroundItems() == null)
					{
						continue;
					}

					for (TileItem item : tile.getGroundItems())
					{
						trackGroundItem(item, tile.getItemLayer());
					}
				}
			}
		}
	}

	@Subscribe
	public void onMenuEntryAdded(MenuEntryAdded event)
	{
		MenuAction menuAction = MenuAction.of(event.getType());
		if (isGroundItemMenuAction(menuAction) && isHiddenAt(event.getIdentifier(), getSelectedTileLocation()))
		{
			client.getMenu().removeMenuEntry(event.getMenuEntry());
			return;
		}

		if (!client.isKeyPressed(KeyCode.KC_SHIFT) || menuAction != MenuAction.EXAMINE_ITEM_GROUND
			|| config.hideRightClickMenuOption())
		{
			return;
		}

		final int itemId = event.getIdentifier();
		rememberItemName(itemId);
		client.getMenu().createMenuEntry(-1)
			.setOption("Hide Ground Item")
			.setTarget(event.getTarget())
			.setType(MenuAction.RUNELITE)
			.onClick(entry ->
			{
				setHideListedItems(true);
				addHiddenItem(itemId);
				panel.refreshSearchResults();
			});
	}

	private boolean isGroundItemMenuAction(MenuAction action)
	{
		return action == MenuAction.GROUND_ITEM_FIRST_OPTION
			|| action == MenuAction.GROUND_ITEM_SECOND_OPTION
			|| action == MenuAction.GROUND_ITEM_THIRD_OPTION
			|| action == MenuAction.GROUND_ITEM_FOURTH_OPTION
			|| action == MenuAction.GROUND_ITEM_FIFTH_OPTION
			|| action == MenuAction.EXAMINE_ITEM_GROUND
			|| action == MenuAction.WIDGET_TARGET_ON_GROUND_ITEM;
	}

	boolean isHidden(int itemId)
	{
		return isHiddenAt(itemId, getCurrentPlayerLocation());
	}

	private boolean isHiddenAt(int itemId, WorldPoint location)
	{
		if (revealHiddenItemsHotkeyPressed)
		{
			return false;
		}

		return hideAll
			|| (hideListedItems && globalHiddenItemIds.contains(itemId))
			|| (hideGroundItemsPluginItems && groundItemsPluginHiddenItemIds.contains(itemId))
			|| isActiveProfileItemHidden(itemId, location);
	}

	boolean isHidden(TileItem item)
	{
		return item != null && !revealHiddenItemsHotkeyPressed && isHiddenIgnoringReveal(item);
	}

	boolean isHiddenIgnoringReveal(TileItem item)
	{
		if (item == null)
		{
			return false;
		}

		if (hideAll || (hideListedItems && globalHiddenItemIds.contains(item.getId()))
			|| (hideGroundItemsPluginItems && groundItemsPluginHiddenItemIds.contains(item.getId())))
		{
			return true;
		}

		ItemLayer layer = trackedGroundItems.get(item);
		WorldPoint location = layer == null ? null : getWorldLocation(layer);
		// A bounded profile must not fall back to the player's location here. The render
		// callback can see a TileItem before its ItemLayer has been tracked; using the
		// player's region in that case would hide the same ID everywhere in the scene.
		return isActiveProfileItemHidden(item.getId(), location);
	}

