	{
		return hideAll;
	}

	boolean isHideListedItems()
	{
		return hideListedItems;
	}

	boolean isHideGroundItemLabels()
	{
		return hideGroundItemLabels;
	}

	boolean isHideGroundItemsPluginItems()
	{
		return hideGroundItemsPluginItems;
	}

	boolean isRevealHiddenItemsHotkeyPressed()
	{
		return revealHiddenItemsHotkeyPressed;
	}

	String getGroundItemDisplayName(TileItem item)
	{
		rememberItemName(item.getId());
		String name = getItemName(item.getId());
		if (item.getQuantity() > 1)
		{
			name += " (" + item.getQuantity() + ")";
		}
		return name;
	}

	boolean isGlobalHiddenItem(int itemId)
	{
		return hideListedItems && globalHiddenItemIds.contains(itemId);
	}

	void setRevealItemHitboxes(List<RevealItemHitbox> hitboxes)
	{
		revealItemHitboxes = Collections.unmodifiableList(new ArrayList<>(hitboxes));
	}

	void clearRevealItemHitboxes()
	{
		revealItemHitboxes = Collections.emptyList();
	}

	private RevealItemHitbox findRevealItemHitbox(Point point)
	{
		for (RevealItemHitbox hitbox : revealItemHitboxes)
		{
			if (hitbox.bounds.contains(point))
			{
				return hitbox;
			}
		}
		return null;
	}

	Client getClient()
	{
		return client;
	}

	Set<TileItem> getTrackedGroundItems()
	{
		return trackedGroundItems.keySet();
	}

	ItemLayer getItemLayer(TileItem item)
	{
		return trackedGroundItems.get(item);
	}

	boolean layerHasHiddenItem(ItemLayer layer)
	{
		Set<TileItem> items = itemsByLayer.get(layer);
		if (items == null)
		{
			return false;
		}

		for (TileItem item : items)
		{
			if (isHiddenIgnoringReveal(item))
			{
				return true;
			}
		}
		return false;
	}

	private void trackGroundItem(TileItem item, ItemLayer layer)
	{
		trackedGroundItems.put(item, layer);
		itemsByLayer.computeIfAbsent(layer, ignored -> ConcurrentHashMap.newKeySet()).add(item);
	}

	private void untrackGroundItem(TileItem item)
	{
		ItemLayer layer = trackedGroundItems.remove(item);
		if (layer != null)
		{
			Set<TileItem> items = itemsByLayer.get(layer);
			if (items != null && items.remove(item) && items.isEmpty())
			{
				itemsByLayer.remove(layer, items);
			}
		}
	}

	private WorldPoint getCurrentPlayerLocation()
	{
		if (client.getLocalPlayer() == null)
		{
			return null;
		}

		LocalPoint localLocation = client.getLocalPlayer().getLocalLocation();
		if (localLocation != null)
		{
			WorldPoint instanceLocation = WorldPoint.fromLocalInstance(client, localLocation, client.getPlane());
			if (instanceLocation != null)
			{
				return instanceLocation;
			}
		}
		return client.getLocalPlayer().getWorldLocation();
	}

