			}
		}
		return layer.getWorldLocation();
	}

	private boolean isActiveProfileItemHidden(int itemId, WorldPoint location)
	{
		if (!hideListedItems || !activeProfileItemIds.contains(itemId))
		{
			return false;
		}

		for (ActiveProfileData profile : activeProfiles)
		{
			boolean isCurrentProfileBeingShown = profileEditing
				&& showProfileHiddenItemsWhileEditing
				&& profileEditingName != null
				&& profile.name.equals(profileEditingName);
			if (isCurrentProfileBeingShown)
			{
				continue;
			}

			if (!profile.itemIds.contains(itemId))
			{
				continue;
			}

			if (profile.regionIds.isEmpty() && profile.boundary.isEmpty())
			{
				return true;
			}
			if (location != null && (profile.regionIds.contains(location.getRegionID())
				|| profile.boundary.matches(location)))
			{
				return true;
			}
		}
		return false;
	}

	boolean isBoundarySelectionActive()
	{
		return boundarySelectionActive;
	}

