	boolean beginBoundarySelection(boolean polygonMode)
	{
		if (!profileEditing || client.getGameState() != GameState.LOGGED_IN)
		{
			return false;
		}

		ProfileBoundary draft = profileDraftBoundary == null ? ProfileBoundary.empty() : profileDraftBoundary;
		boundarySelectionTiles = Collections.unmodifiableSet(new java.util.LinkedHashSet<>(draft.tiles));
		boundarySelectionPolygons = copyPolygons(draft.polygons);
		boundarySelectionVertices = Collections.emptyList();
		boundarySelectionAnchor = null;
		boundaryEditingExisting = !draft.isEmpty();
		boundarySelectionFlattened = false;
		boundaryPolygonMode = polygonMode;
		boundarySelectionActive = true;
		rebuildBoundarySelectionPreview();
		clientThread.invoke(() ->
		{
			net.runelite.api.Point mousePosition = client.getMouseCanvasPosition();
			if (mousePosition != null)
			{
				updateHoveredBoundaryTile(new Point(mousePosition.getX(), mousePosition.getY()), false);
			}
		});
		panel.refresh();
		return true;
	}

	void finishBoundarySelection()
	{
		if (!boundarySelectionActive)
		{
			return;
		}

		List<List<TileCoordinate>> polygons = new ArrayList<>(boundarySelectionPolygons);
		if (boundarySelectionVertices.size() >= 3)
		{
			polygons.add(Collections.unmodifiableList(new ArrayList<>(boundarySelectionVertices)));
		}

		// A polygon is only an editing aid. Once selection is finished, persist the
		// concrete tiles so the saved profile does not retain vertex geometry or
		// need to rasterize polygons during item visibility checks.
		Set<TileCoordinate> tiles = new java.util.LinkedHashSet<>(boundarySelectionTiles);
		boolean flattened = true;
		for (List<TileCoordinate> polygon : polygons)
		{
			Set<TileCoordinate> filled = rasterizePolygon(polygon);
			if (filled.isEmpty())
			{
				flattened = false;
				break;
			}
			tiles.addAll(filled);
		}
		profileDraftBoundary = flattened
			? new ProfileBoundary(tiles, Collections.emptyList())
			: new ProfileBoundary(boundarySelectionTiles, polygons);
		rebuildProfileDraftBoundaryPreview();
		clearBoundarySelectionState();
		panel.scheduleProfileAutoSave();
		panel.refresh();
	}

	void cancelBoundarySelection()
	{
		if (!boundarySelectionActive)
		{
			return;
		}

		clearBoundarySelectionState();
		panel.refresh();
	}

	void clearProfileBoundary()
	{
		if (!profileEditing)
		{
			return;
		}

		profileDraftBoundary = ProfileBoundary.empty();
		profileDraftBoundaryPreviewTiles = Collections.emptySet();
		boundarySelectionTiles = Collections.emptySet();
		boundarySelectionVertices = Collections.emptyList();
		boundarySelectionPolygons = Collections.emptyList();
		boundarySelectionPreviewTiles = Collections.emptySet();
		boundaryEditingExisting = false;
		boundarySelectionFlattened = false;
		panel.scheduleProfileAutoSave();
		panel.refresh();
	}

