	String getBoundarySelectionSummary()
	{
		ProfileBoundary boundary = boundarySelectionActive
			? new ProfileBoundary(boundarySelectionTiles, boundarySelectionPolygons)
			: profileDraftBoundary;
		if (boundary == null || boundary.isEmpty())
		{
			return "No tile boundary selected.";
		}

		int polygonCount = boundary.polygons.size();
		return boundary.tiles.size() + " tile" + (boundary.tiles.size() == 1 ? "" : "s")
			+ (polygonCount == 0 ? "" : ", " + polygonCount + " polygon" + (polygonCount == 1 ? "" : "s"));
	}

	private void clearBoundarySelectionState()
	{
		boundarySelectionActive = false;
		boundarySelectionAnchor = null;
		boundarySelectionVertices = Collections.emptyList();
		boundarySelectionPolygons = Collections.emptyList();
		boundarySelectionPreviewTiles = Collections.emptySet();
		hoveredBoundaryTile = null;
		boundaryEditingExisting = false;
		boundarySelectionFlattened = false;
		boundaryPolygonMode = false;
	}

	private void rebuildProfileDraftBoundaryPreview()
	{
		ProfileBoundary boundary = profileDraftBoundary;
		if (boundary == null || boundary.isEmpty())
		{
			profileDraftBoundaryPreviewTiles = Collections.emptySet();
			return;
		}

		Set<TileCoordinate> previewTiles = new java.util.LinkedHashSet<>(boundary.tiles);
		for (List<TileCoordinate> polygon : boundary.polygons)
		{
			previewTiles.addAll(rasterizePolygon(polygon));
		}
		profileDraftBoundaryPreviewTiles = Collections.unmodifiableSet(previewTiles);
	}

	private boolean flattenBoundarySelection()
	{
		if (boundarySelectionFlattened || boundarySelectionPolygons.isEmpty())
		{
			boundarySelectionFlattened = true;
			return true;
		}

		Set<TileCoordinate> tiles = new java.util.LinkedHashSet<>(boundarySelectionTiles);
		for (List<TileCoordinate> polygon : boundarySelectionPolygons)
		{
			Set<TileCoordinate> filled = rasterizePolygon(polygon);
			if (filled.isEmpty())
			{
				// Do not discard a large polygon that is intentionally outside the
				// preview rasterization limit.
				return false;
			}
			tiles.addAll(filled);
		}
		boundarySelectionTiles = Collections.unmodifiableSet(tiles);
		boundarySelectionPolygons = Collections.emptyList();
		boundarySelectionFlattened = true;
		rebuildBoundarySelectionPreview();
		return true;
	}

	private void handleBoundaryLeftClick(MouseEvent event)
	{
		TileCoordinate tile = hoveredBoundaryTile;
		if (tile == null)
		{
			return;
		}

		boolean tileIsHighlighted = boundarySelectionPreviewTiles.contains(tile);
		if (!boundaryPolygonMode && !event.isShiftDown() && !event.isControlDown())
		{
			if (boundaryEditingExisting && tileIsHighlighted && !flattenBoundarySelection())
			{
				return;
			}

			Set<TileCoordinate> tiles = new java.util.LinkedHashSet<>(boundarySelectionTiles);
			if (!tiles.add(tile))
			{
				tiles.remove(tile);
			}
			boundarySelectionTiles = Collections.unmodifiableSet(tiles);
			rebuildBoundarySelectionPreview();
			return;
		}
		if (boundaryEditingExisting && tileIsHighlighted && boundarySelectionVertices.isEmpty() && !event.isShiftDown()
			&& !flattenBoundarySelection())
		{
			return;
		}

		if (!event.isShiftDown() && !event.isControlDown())
		{
			if (boundaryEditingExisting && tileIsHighlighted && boundarySelectionVertices.isEmpty())
			{
				Set<TileCoordinate> tiles = new java.util.LinkedHashSet<>(boundarySelectionTiles);
				if (!tiles.add(tile))
				{
					tiles.remove(tile);
				}
				boundarySelectionTiles = Collections.unmodifiableSet(tiles);
				rebuildBoundarySelectionPreview();
				return;
			}

			List<TileCoordinate> vertices = new ArrayList<>(boundarySelectionVertices);
			if (vertices.size() >= 3 && tile.equals(vertices.get(0)))
			{
				List<List<TileCoordinate>> polygons = new ArrayList<>(boundarySelectionPolygons);
				polygons.add(Collections.unmodifiableList(vertices));
				boundarySelectionPolygons = Collections.unmodifiableList(polygons);
				boundarySelectionVertices = Collections.emptyList();
			}
			else if (!vertices.contains(tile))
			{
				vertices.add(tile);
				boundarySelectionVertices = Collections.unmodifiableList(vertices);
			}
			rebuildBoundarySelectionPreview();
			return;
		}

		Set<TileCoordinate> tiles = new java.util.LinkedHashSet<>(boundarySelectionTiles);
		if (event.isControlDown() && boundaryEditingExisting && tileIsHighlighted
			&& !flattenBoundarySelection())
		{
			return;
		}
		if (event.isShiftDown())
		{
			if (boundarySelectionAnchor == null)
			{
				boundarySelectionAnchor = tile;
				tiles.add(tile);
			}
			else
			{
				addRectangle(tiles, boundarySelectionAnchor, tile);
				boundarySelectionAnchor = null;
			}
		}
		else
		{
			boundarySelectionAnchor = null;
			if (!tiles.add(tile))
			{
				tiles.remove(tile);
			}
		}
		boundarySelectionTiles = Collections.unmodifiableSet(tiles);
		rebuildBoundarySelectionPreview();
	}

	private void addRectangle(Set<TileCoordinate> tiles, TileCoordinate first, TileCoordinate second)
	{
		if (first.plane != second.plane)
		{
			return;
		}

		long width = Math.abs((long) second.x - first.x) + 1;
		long height = Math.abs((long) second.y - first.y) + 1;
		if (width * height > 20000)
		{
			return;
		}

		int minX = Math.min(first.x, second.x);
		int maxX = Math.max(first.x, second.x);
		int minY = Math.min(first.y, second.y);
		int maxY = Math.max(first.y, second.y);
		for (int x = minX; x <= maxX; x++)
		{
			for (int y = minY; y <= maxY; y++)
			{
				tiles.add(new TileCoordinate(x, y, first.plane));
			}
		}
	}

	private void rebuildBoundarySelectionPreview()
	{
		Set<TileCoordinate> preview = new java.util.LinkedHashSet<>(boundarySelectionTiles);
		for (List<TileCoordinate> polygon : boundarySelectionPolygons)
		{
			preview.addAll(rasterizePolygon(polygon));
		}
		if (boundarySelectionVertices.size() >= 3)
		{
			preview.addAll(rasterizePolygon(boundarySelectionVertices));
		}
		boundarySelectionPreviewTiles = Collections.unmodifiableSet(preview);
	}

	private static Set<TileCoordinate> rasterizePolygon(List<TileCoordinate> vertices)
	{
		if (vertices == null || vertices.size() < 3)
		{
			return Collections.emptySet();
		}

		int plane = vertices.get(0).plane;
		int minX = Integer.MAX_VALUE;
		int maxX = Integer.MIN_VALUE;
		int minY = Integer.MAX_VALUE;
		int maxY = Integer.MIN_VALUE;
		for (TileCoordinate vertex : vertices)
		{
			if (vertex.plane != plane)
			{
				return Collections.emptySet();
			}
			minX = Math.min(minX, vertex.x);
			maxX = Math.max(maxX, vertex.x);
			minY = Math.min(minY, vertex.y);
			maxY = Math.max(maxY, vertex.y);
		}
		long area = ((long) maxX - minX + 1) * ((long) maxY - minY + 1);
		if (area > 20000)
		{
			return Collections.emptySet();
		}

		Set<TileCoordinate> filled = new java.util.LinkedHashSet<>();
		for (int x = minX; x <= maxX; x++)
		{
			for (int y = minY; y <= maxY; y++)
			{
				if (polygonIntersectsTile(vertices, x, y))
				{
					filled.add(new TileCoordinate(x, y, plane));
				}
			}
		}
		return filled;
	}

	private static boolean polygonIntersectsTile(List<TileCoordinate> vertices, int tileX, int tileY)
	{
		// A center-only test leaves holes along diagonal edges and excludes narrow
		// sections of a polygon. Include any tile whose square touches the polygon.
		if (pointInPolygon(vertices, tileX + 0.5d, tileY + 0.5d))
		{
			return true;
		}

		double left = tileX;
		double right = tileX + 1d;
		double bottom = tileY;
		double top = tileY + 1d;
		for (TileCoordinate vertex : vertices)
		{
			double vertexX = vertex.x + 0.5d;
			double vertexY = vertex.y + 0.5d;
			if (vertexX >= left && vertexX <= right && vertexY >= bottom && vertexY <= top)
			{
				return true;
			}
		}

		if (pointInPolygon(vertices, left, bottom) || pointInPolygon(vertices, left, top)
			|| pointInPolygon(vertices, right, bottom) || pointInPolygon(vertices, right, top))
		{
			return true;
		}

		for (int index = 0; index < vertices.size(); index++)
		{
			TileCoordinate first = vertices.get(index);
			TileCoordinate second = vertices.get((index + 1) % vertices.size());
			double firstX = first.x + 0.5d;
			double firstY = first.y + 0.5d;
			double secondX = second.x + 0.5d;
			double secondY = second.y + 0.5d;
			if (Line2D.linesIntersect(firstX, firstY, secondX, secondY, left, bottom, right, bottom)
				|| Line2D.linesIntersect(firstX, firstY, secondX, secondY, right, bottom, right, top)
				|| Line2D.linesIntersect(firstX, firstY, secondX, secondY, right, top, left, top)
				|| Line2D.linesIntersect(firstX, firstY, secondX, secondY, left, top, left, bottom))
			{
				return true;
			}
		}
		return false;
	}

	private static boolean pointInPolygon(List<TileCoordinate> vertices, double x, double y)
	{
		boolean inside = false;
		for (int i = 0, j = vertices.size() - 1; i < vertices.size(); j = i++)
		{
			TileCoordinate current = vertices.get(i);
			TileCoordinate previous = vertices.get(j);
			double currentX = current.x + 0.5d;
			double currentY = current.y + 0.5d;
			double previousX = previous.x + 0.5d;
			double previousY = previous.y + 0.5d;
			if ((currentY > y) != (previousY > y)
				&& x < (previousX - currentX) * (y - currentY)
				/ (previousY - currentY) + currentX)
			{
				inside = !inside;
			}
		}
		return inside;
	}

	private void updateHoveredBoundaryTile(Point mousePosition, boolean exhaustive)
	{
		if (!boundarySelectionActive || mousePosition == null)
		{
			return;
		}

		Tile tile = findTileAt(mousePosition, exhaustive);
		hoveredBoundaryTile = tile == null ? null : toTileCoordinate(tile);
	}

	private Tile findTileAt(Point mousePosition, boolean exhaustive)
	{
		net.runelite.api.WorldView worldView = client.getTopLevelWorldView();
		if (worldView == null || worldView.getScene() == null || mousePosition == null)
		{
			return null;
		}

		Tile selectedTile = worldView.getSelectedSceneTile();
		Tile tile = chooseContainingTile(selectedTile, mousePosition.x, mousePosition.y);
		if (tile != null)
		{
			return tile;
		}

		// Mouse movement remains bounded and inexpensive. A press gets the
		// exhaustive fallback below so it remains accurate even if RuneLite's
		// selected tile has not caught up with the latest mouse event.
		tile = findNearbySceneTileAtMouse(worldView, selectedTile, mousePosition.x, mousePosition.y);
		if (tile != null || !exhaustive)
		{
			return tile;
		}

		return findAnySceneTileAtMouse(worldView, mousePosition.x, mousePosition.y);
	}

	private Tile findNearbySceneTileAtMouse(net.runelite.api.WorldView worldView, Tile anchor,
		int mouseX, int mouseY)
	{
		if (anchor == null || anchor.getLocalLocation() == null)
		{
			return null;
		}

		Scene scene = worldView.getScene();
		Tile[][][] tiles = scene.getTiles();
		int plane = worldView.getPlane();
		LocalPoint localLocation = anchor.getLocalLocation();
		if (tiles == null || plane < 0 || plane >= tiles.length || tiles[plane] == null)
		{
			return null;
		}

		Tile[][] planeTiles = tiles[plane];
		int anchorX = localLocation.getSceneX();
		int anchorY = localLocation.getSceneY();
		Tile bestTile = null;
		double bestDistanceSquared = Double.MAX_VALUE;
		for (int sceneX = Math.max(0, anchorX - 8); sceneX <= Math.min(planeTiles.length - 1, anchorX + 8); sceneX++)
		{
			Tile[] column = planeTiles[sceneX];
			if (column == null)
			{
				continue;
			}

			for (int sceneY = Math.max(0, anchorY - 8); sceneY <= Math.min(column.length - 1, anchorY + 8); sceneY++)
			{
				Tile candidate = column[sceneY];
				if (candidate == null || candidate.getRenderLevel() != plane)
				{
					continue;
				}

				Tile containing = chooseContainingTile(candidate, mouseX, mouseY);
				if (containing != null)
				{
					double distance = distanceSquaredToTileCenter(containing, mouseX, mouseY);
					if (distance < bestDistanceSquared)
					{
						bestTile = containing;
						bestDistanceSquared = distance;
					}
				}
			}
		}
		return bestTile;
	}

	private Tile findAnySceneTileAtMouse(net.runelite.api.WorldView worldView, int mouseX, int mouseY)
	{
		Tile[][][] tiles = worldView.getScene().getTiles();
		int plane = worldView.getPlane();
		if (tiles == null || plane < 0 || plane >= tiles.length || tiles[plane] == null)
		{
			return null;
		}

		Tile bestTile = null;
		double bestDistanceSquared = Double.MAX_VALUE;
		for (Tile[] column : tiles[plane])
		{
			if (column == null)
			{
				continue;
			}
			for (Tile candidate : column)
			{
				if (candidate == null || candidate.getRenderLevel() != plane)
				{
					continue;
				}
				Tile containing = chooseContainingTile(candidate, mouseX, mouseY);
				if (containing != null)
				{
					double distance = distanceSquaredToTileCenter(containing, mouseX, mouseY);
					if (distance < bestDistanceSquared)
					{
						bestTile = containing;
						bestDistanceSquared = distance;
					}
				}
			}
		}
		return bestTile;
	}

	private Tile chooseContainingTile(Tile candidate, int mouseX, int mouseY)
	{
		if (candidate == null || candidate.getLocalLocation() == null)
		{
			return null;
		}

		Polygon tilePolygon = Perspective.getCanvasTilePoly(client, candidate.getLocalLocation());
		return tilePolygon != null && tilePolygon.contains(mouseX, mouseY) ? candidate : null;
	}

	private double distanceSquaredToTileCenter(Tile tile, int mouseX, int mouseY)
	{
		Polygon tilePolygon = Perspective.getCanvasTilePoly(client, tile.getLocalLocation());
		if (tilePolygon == null)
		{
			return Double.MAX_VALUE;
		}

		double dx = tilePolygon.getBounds().getCenterX() - mouseX;
		double dy = tilePolygon.getBounds().getCenterY() - mouseY;
		return dx * dx + dy * dy;
	}

	private TileCoordinate toTileCoordinate(Tile tile)
	{
		WorldPoint worldLocation = toTileWorldPoint(tile);
		if (worldLocation == null)
		{
			return null;
		}
		return new TileCoordinate(worldLocation.getX(), worldLocation.getY(), worldLocation.getPlane());
	}

	private WorldPoint toTileWorldPoint(Tile tile)
	{
		LocalPoint localLocation = tile.getLocalLocation();
		return localLocation == null
			? tile.getWorldLocation()
			: WorldPoint.fromLocalInstance(client, localLocation, tile.getPlane());
	}

	private static List<List<TileCoordinate>> copyPolygons(List<List<TileCoordinate>> polygons)
	{
		List<List<TileCoordinate>> copy = new ArrayList<>();
		for (List<TileCoordinate> polygon : polygons)
		{
			copy.add(Collections.unmodifiableList(new ArrayList<>(polygon)));
		}
		return Collections.unmodifiableList(copy);
	}

	void addHiddenItem(int itemId)
	{
		addHiddenItems(Collections.singletonList(itemId));
	}

	void addHiddenItems(Collection<Integer> itemIds)
	{
		Set<Integer> ids = new HashSet<>(globalHiddenItemIds);
		if (ids.addAll(itemIds))
		{
			setHideListedItems(true);
			setHiddenItemIds(ids);
		}
	}

	void beginProfileEdit(String profileName)
	{
		Set<Integer> ids = savedProfiles.get(profileName);
		if (ids != null)
		{
			profileDraftItemIds = new HashSet<>(ids);
			profileDraftIsNew = false;
			profileEditingName = profileName;
			showProfileHiddenItemsWhileEditing = true;
			profileDraftBoundary = copyBoundary(savedProfileBoundaries.get(profileName));
			rebuildProfileDraftBoundaryPreview();
			profileEditing = true;
			resolveItemNames(profileDraftItemIds);
		}
	}

	boolean beginNewProfileEdit(String profileName)
	{
		String name = normalizeProfileName(profileName);
		if (name == null || savedProfiles.containsKey(name))
		{
			return false;
		}

		profileDraftItemIds = new HashSet<>();
		profileDraftIsNew = true;
		profileEditingName = null;
		showProfileHiddenItemsWhileEditing = true;
		profileDraftBoundary = ProfileBoundary.empty();
		rebuildProfileDraftBoundaryPreview();
		profileEditing = true;
		return true;
	}

	boolean profileNameExists(String profileName)
	{
		String name = normalizeProfileName(profileName);
		return name != null && savedProfiles.containsKey(name);
	}

	void cancelProfileEdit()
	{
		cancelBoundarySelection();
		profileDraftItemIds = null;
		profileDraftIsNew = false;
		profileEditingName = null;
		showProfileHiddenItemsWhileEditing = true;
		profileDraftBoundary = null;
		profileDraftBoundaryPreviewTiles = Collections.emptySet();
		profileEditing = false;
	}

	String saveProfileEdit(String oldProfileName, String newProfileName, Collection<Integer> regionIds)
	{
		if (boundarySelectionActive)
		{
			finishBoundarySelection();
		}

		String savedName = saveProfileEditInternal(oldProfileName, newProfileName, regionIds);
		if (savedName != null)
		{
			endProfileEdit();
		}
		return savedName;
	}

