	private String saveProfileEditInternal(String oldProfileName, String newProfileName,
		Collection<Integer> regionIds)
	{
		String oldName = normalizeProfileName(oldProfileName);
		String name = normalizeProfileName(newProfileName);
		if (name == null || (!profileDraftIsNew
			&& (oldName == null || !savedProfiles.containsKey(oldName)))
			|| (profileDraftIsNew && oldName != null)
			|| ((profileDraftIsNew || !name.equals(oldName)) && savedProfiles.containsKey(name)))
		{
			return null;
		}

		Set<Integer> draft = profileDraftItemIds;
		if (draft == null)
		{
			return null;
		}

		boolean wasActive = oldName != null && activeProfileNames.contains(oldName);
		boolean activateNewProfile = profileDraftIsNew;
		Map<String, Set<Integer>> profiles = new LinkedHashMap<>(savedProfiles);
		Map<String, Set<Integer>> regions = new LinkedHashMap<>(savedProfileRegions);
		Map<String, ProfileBoundary> boundaries = new LinkedHashMap<>(savedProfileBoundaries);
		if (oldName != null && !oldName.equals(name))
		{
			profiles.remove(oldName);
			regions.remove(oldName);
			boundaries.remove(oldName);
			if (wasActive)
			{
				Set<String> renamedActiveProfiles = new LinkedHashSet<>(activeProfileNames);
				renamedActiveProfiles.remove(oldName);
				renamedActiveProfiles.add(name);
				activeProfileNames = Collections.unmodifiableSet(renamedActiveProfiles);
			}
		}
		profiles.put(name, new HashSet<>(draft));
		regions.put(name, normalizeRegionIds(regionIds));
		boundaries.put(name, copyBoundary(profileDraftBoundary));
		if (activateNewProfile)
		{
			Set<String> updatedActiveProfiles = new LinkedHashSet<>(activeProfileNames);
			updatedActiveProfiles.add(name);
			activeProfileNames = Collections.unmodifiableSet(updatedActiveProfiles);
		}
		setSavedProfiles(profiles, regions, boundaries);
		if (wasActive || activateNewProfile)
		{
			persistActiveProfiles(activeProfileNames);
		}

		profileDraftIsNew = false;
		profileEditingName = name;
		return name;
	}

