	void searchItems(String query)
	{
		String search = query.trim().toLowerCase();
		if (search.isEmpty())
		{
			panel.showSearchResults(Collections.emptyList());
			return;
		}

		clientThread.invoke(() ->
		{
			Set<Integer> searchHiddenIds = profileDraftItemIds == null
				? globalHiddenItemIds
				: profileDraftItemIds;
			if (searchableItems == null)
			{
				List<ItemSearchResult> catalog = new ArrayList<>();
				Set<Integer> catalogIds = new HashSet<>();
				for (int itemId = 0; itemId < client.getItemCount(); itemId++)
				{
					final net.runelite.api.ItemComposition composition = itemManager.getItemComposition(itemId);
					String name = composition.getName();
					if (name == null || name.equalsIgnoreCase("null") || !catalogIds.add(composition.getId()))
					{
						continue;
					}

					itemNames.put(composition.getId(), name);
					catalog.add(new ItemSearchResult(composition.getId(), name, composition.getNote() != -1));
				}
				searchableItems = Collections.unmodifiableList(catalog);
			}

			try
			{
				int requestedId = Integer.parseInt(search);
				for (ItemSearchResult result : searchableItems)
				{
					if (result.id == requestedId
						&& (!removeHiddenItemsFromSearch || !searchHiddenIds.contains(requestedId)))
					{
						if (!groupItemsByName)
						{
							panel.showSearchResults(Collections.singletonList(result));
							return;
						}

						List<Integer> matchingIds = new ArrayList<>();
						String normalizedName = normalizeSearchName(result.name);
						for (ItemSearchResult variant : searchableItems)
						{
							if (removeHiddenItemsFromSearch
								&& normalizeSearchName(variant.name).equals(normalizedName)
								&& searchHiddenIds.contains(variant.id))
							{
								panel.showSearchResults(Collections.emptyList());
								return;
							}
						}
						for (ItemSearchResult variant : searchableItems)
						{
							if (normalizeSearchName(variant.name).equals(normalizedName))
							{
								matchingIds.add(variant.id);
							}
						}
						matchingIds.sort(Integer::compareTo);
						ItemSearchResult displayResult = result;
						for (ItemSearchResult variant : searchableItems)
						{
							if (normalizeSearchName(variant.name).equals(normalizedName) && !variant.noted)
							{
								displayResult = variant;
								break;
							}
						}
						panel.showSearchResults(Collections.singletonList(new ItemSearchResult(displayResult.name, matchingIds)));
						return;
					}
				}
				panel.showSearchResults(Collections.emptyList());
				return;
			}
			catch (NumberFormatException ignored)
			{
				// Continue with a name search.
			}

			Map<String, List<ItemSearchResult>> groupedResults = new LinkedHashMap<>();
			for (ItemSearchResult result : searchableItems)
			{
				if (result.name.toLowerCase().contains(search)
					&& (!removeHiddenItemsFromSearch || groupItemsByName || !searchHiddenIds.contains(result.id)))
				{
					if (groupItemsByName)
					{
						groupedResults.computeIfAbsent(normalizeSearchName(result.name), ignored -> new ArrayList<>()).add(result);
					}
					else
					{
						groupedResults.computeIfAbsent(result.name + "\u0000" + result.id, ignored -> new ArrayList<>()).add(result);
					}
				}
			}

			List<ItemSearchResult> results = new ArrayList<>();
			for (List<ItemSearchResult> group : groupedResults.values())
			{
				if (removeHiddenItemsFromSearch
					&& groupItemsByName
					&& group.stream().anyMatch(result -> searchHiddenIds.contains(result.id)))
				{
					continue;
				}
				group.sort(Comparator
					.comparing((ItemSearchResult result) -> result.noted)
					.thenComparing(result -> result.name.toLowerCase())
					.thenComparingInt(result -> result.id));
				List<Integer> ids = new ArrayList<>();
				for (ItemSearchResult result : group)
				{
					ids.add(result.id);
				}
				results.add(new ItemSearchResult(group.get(0).name, ids));
			}

			results.sort(Comparator
				.comparingInt((ItemSearchResult result) -> searchRelevance(result.name, search))
				.thenComparing(result -> normalizeSearchName(result.name)));
			if (results.size() > 25)
			{
				results = new ArrayList<>(results.subList(0, 25));
			}
			panel.showSearchResults(results);
		});
	}

