	static final class ProfileBoundary
	{
		Set<TileCoordinate> tiles = Collections.emptySet();
		List<List<TileCoordinate>> polygons = Collections.emptyList();

		ProfileBoundary()
		{
		}

		ProfileBoundary(Collection<TileCoordinate> tiles, Collection<List<TileCoordinate>> polygons)
		{
			this.tiles = Collections.unmodifiableSet(new java.util.LinkedHashSet<>(tiles));
			this.polygons = copyPolygons(new ArrayList<>(polygons));
		}

		static ProfileBoundary empty()
		{
			return new ProfileBoundary(Collections.emptySet(), Collections.emptyList());
		}

		boolean isEmpty()
		{
			return (tiles == null || tiles.isEmpty()) && (polygons == null || polygons.isEmpty());
		}

		boolean matches(WorldPoint point)
		{
			if (point == null)
			{
				return false;
			}
			if (tiles != null && tiles.contains(new TileCoordinate(point.getX(), point.getY(), point.getPlane())))
			{
				return true;
			}
			if (polygons != null)
			{
				for (List<TileCoordinate> polygon : polygons)
				{
					if (polygon.stream().allMatch(vertex -> vertex.plane == point.getPlane())
						&& pointInPolygon(polygon, point.getX() + 0.5d, point.getY() + 0.5d))
					{
						return true;
					}
				}
			}
			return false;
		}
	}

	private static ProfileBoundary copyBoundary(ProfileBoundary boundary)
	{
		if (boundary == null)
		{
			return ProfileBoundary.empty();
		}
		return new ProfileBoundary(
			boundary.tiles == null ? Collections.emptySet() : boundary.tiles,
			boundary.polygons == null ? Collections.emptyList() : boundary.polygons);
	}

	private static String normalizeSearchName(String name)
	{
		String normalized = name.trim().toLowerCase();
		if (normalized.endsWith(" (noted)"))
		{
			return normalized.substring(0, normalized.length() - " (noted)".length());
		}
		return normalized;
	}

	private static int searchRelevance(String name, String search)
	{
		String normalizedName = normalizeSearchName(name);
		if (normalizedName.equals(search))
		{
			return 0;
		}
		if (normalizedName.startsWith(search))
		{
			return 1;
		}
		return 2;
	}

