		}

		JsonObject root = new JsonObject();
		root.addProperty("format", 2);
		root.addProperty("name", profileName);
		JsonArray hiddenIds = new JsonArray();
		List<Integer> sortedItemIds = new ArrayList<>(itemIds);
		sortedItemIds.sort(Integer::compareTo);
		for (int itemId : sortedItemIds)
		{
			hiddenIds.add(itemId);
		}
		root.add("hiddenItemIds", hiddenIds);
		JsonArray regionIds = new JsonArray();
		for (int regionId : getSavedProfileRegions(profileName))
		{
			regionIds.add(regionId);
		}
		root.add("regionIds", regionIds);

		ProfileBoundary boundary = copyBoundary(savedProfileBoundaries.get(profileName));
		root.add("tiles", gson.toJsonTree(boundary.tiles));
		root.add("polygons", gson.toJsonTree(boundary.polygons));
		return gson.toJson(root);
	}

