	ProfileImportResult importProfileJson(String json, boolean overwrite)
	{
		try
		{
			JsonObject root = gson.fromJson(json, JsonObject.class);
			if (root == null || !root.has("format")
				|| (root.get("format").getAsInt() != 1 && root.get("format").getAsInt() != 2))
			{
				return ProfileImportResult.error("Unsupported or missing profile format.");
			}

			String name = normalizeProfileName(root.has("name") ? root.get("name").getAsString() : null);
			if (name == null)
			{
				return ProfileImportResult.error("The profile needs a name.");
			}

			Set<Integer> itemIds = parseProfileIdArray(root.get("hiddenItemIds"), "hiddenItemIds", 10000);
			Set<Integer> regionIds = parseProfileIdArray(root.get("regionIds"), "regionIds", 256);
			if (itemIds == null || regionIds == null)
			{
				return ProfileImportResult.error("Profile IDs must be non-negative integers in arrays.");
			}
			ProfileBoundary boundary = parseProfileBoundary(root);
			if (boundary == null)
			{
				return ProfileImportResult.error("Profile tiles and polygons are invalid.");
			}

			if (savedProfiles.containsKey(name) && !overwrite)
			{
				return ProfileImportResult.existing(name);
			}

			saveProfileData(name, itemIds, regionIds, boundary);
			return ProfileImportResult.imported(name);
		}
		catch (RuntimeException ex)
		{
			return ProfileImportResult.error("The profile JSON could not be read.");
		}
	}

	private static Set<Integer> parseProfileIdArray(JsonElement element, String key, int maximumSize)
	{
		if (element == null || !element.isJsonArray())
		{
			return key.equals("hiddenItemIds") ? null : Collections.emptySet();
		}

		JsonArray array = element.getAsJsonArray();
		if (array.size() > maximumSize)
		{
			return null;
		}

		Set<Integer> ids = new java.util.TreeSet<>();
		for (JsonElement value : array)
		{
			if (!value.isJsonPrimitive() || !value.getAsJsonPrimitive().isNumber())
			{
				return null;
			}

			int id = value.getAsInt();
			if (id < 0)
			{
				return null;
			}
			ids.add(id);
		}
		return ids;
	}

	private static ProfileBoundary parseProfileBoundary(JsonObject root)
	{
		Set<TileCoordinate> tiles = new java.util.LinkedHashSet<>();
		JsonElement tileElement = root.get("tiles");
		if (tileElement != null)
		{
			if (!tileElement.isJsonArray() || tileElement.getAsJsonArray().size() > 20000)
			{
				return null;
			}
			for (JsonElement value : tileElement.getAsJsonArray())
			{
				TileCoordinate tile = parseTileCoordinate(value);
				if (tile == null)
				{
					return null;
				}
				tiles.add(tile);
			}
		}

		List<List<TileCoordinate>> polygons = new ArrayList<>();
		JsonElement polygonElement = root.get("polygons");
		if (polygonElement != null)
		{
			if (!polygonElement.isJsonArray() || polygonElement.getAsJsonArray().size() > 128)
			{
				return null;
			}
			for (JsonElement polygonValue : polygonElement.getAsJsonArray())
			{
				if (!polygonValue.isJsonArray() || polygonValue.getAsJsonArray().size() < 3
					|| polygonValue.getAsJsonArray().size() > 64)
				{
					return null;
				}
				List<TileCoordinate> polygon = new ArrayList<>();
				for (JsonElement vertexValue : polygonValue.getAsJsonArray())
				{
					TileCoordinate vertex = parseTileCoordinate(vertexValue);
					if (vertex == null)
					{
						return null;
					}
					polygon.add(vertex);
				}
				polygons.add(Collections.unmodifiableList(polygon));
			}
		}
		return new ProfileBoundary(tiles, polygons);
	}

	private static TileCoordinate parseTileCoordinate(JsonElement element)
	{
		if (!element.isJsonObject())
		{
			return null;
		}
		JsonObject object = element.getAsJsonObject();
		if (!object.has("x") || !object.has("y") || !object.has("plane")
			|| !object.get("x").isJsonPrimitive() || !object.get("y").isJsonPrimitive()
			|| !object.get("plane").isJsonPrimitive()
			|| !object.getAsJsonPrimitive("x").isNumber()
			|| !object.getAsJsonPrimitive("y").isNumber()
			|| !object.getAsJsonPrimitive("plane").isNumber())
		{
			return null;
		}
		try
		{
			int x = object.get("x").getAsInt();
			int y = object.get("y").getAsInt();
			int plane = object.get("plane").getAsInt();
			if (object.get("x").getAsDouble() != x || object.get("y").getAsDouble() != y
				|| object.get("plane").getAsDouble() != plane)
			{
				return null;
			}
			return x >= 0 && x <= 16383 && y >= 0 && y <= 16383 && plane >= 0 && plane <= 3
				? new TileCoordinate(x, y, plane) : null;
		}
		catch (RuntimeException ex)
		{
			return null;
		}
	}

	static final class ProfileImportResult
	{
		final String message;
		final String profileName;
		final boolean imported;
		final boolean existing;

		private ProfileImportResult(String message, String profileName, boolean imported, boolean existing)
		{
			this.message = message;
			this.profileName = profileName;
			this.imported = imported;
			this.existing = existing;
		}

		static ProfileImportResult imported(String profileName)
		{
			return new ProfileImportResult("Imported profile: " + profileName, profileName, true, false);
		}

		static ProfileImportResult existing(String profileName)
		{
			return new ProfileImportResult("A profile with this name already exists.", profileName, false, true);
		}

		static ProfileImportResult error(String message)
		{
			return new ProfileImportResult(message, null, false, false);
		}
	}

	void setProfileActive(String profileName, boolean active)
	{
		if (!savedProfiles.containsKey(profileName))
		{
			return;
		}

		Set<String> updatedNames = new LinkedHashSet<>(activeProfileNames);
		if (active)
		{
			updatedNames.add(profileName);
		}
		else
		{
			updatedNames.remove(profileName);
		}
		activeProfileNames = Collections.unmodifiableSet(updatedNames);
		persistActiveProfiles(activeProfileNames);
		rebuildActiveProfileCache();
		rebuildEffectiveHiddenItems();
	}

	void deleteProfile(String profileName)
	{
		if (!savedProfiles.containsKey(profileName))
		{
			return;
		}

		Map<String, Set<Integer>> profiles = new LinkedHashMap<>(savedProfiles);
		Map<String, Set<Integer>> regions = new LinkedHashMap<>(savedProfileRegions);
		profiles.remove(profileName);
		regions.remove(profileName);
		if (activeProfileNames.contains(profileName))
		{
			Set<String> updatedNames = new LinkedHashSet<>(activeProfileNames);
			updatedNames.remove(profileName);
			activeProfileNames = Collections.unmodifiableSet(updatedNames);
			persistActiveProfiles(activeProfileNames);
			rebuildActiveProfileCache();
		}
		Map<String, ProfileBoundary> boundaries = new LinkedHashMap<>(savedProfileBoundaries);
		boundaries.remove(profileName);
		setSavedProfiles(profiles, regions, boundaries);
	}

	List<String> getGroundItemsOverlaps()
	{
		List<String> overlaps = new ArrayList<>();
		for (int itemId : getGroundItemsOverlapIds())
		{
			String itemName = getItemName(itemId).trim();
			overlaps.add(itemName + " (ID: " + itemId + ")");
		}
		overlaps.sort(String.CASE_INSENSITIVE_ORDER);
		return overlaps;
	}

	Set<Integer> getGroundItemsOverlapIds()
	{
		if (!isGroundItemsPluginActive())
		{
			return Collections.emptySet();
		}

		Set<String> groundItemsNames = new HashSet<>();
		String configuredItems = configManager.getConfiguration("grounditems", "highlightedItems", String.class);
		if (configuredItems == null)
		{
			return Collections.emptySet();
		}

		for (String value : Text.fromCSV(configuredItems))
		{
			String name = value.trim();
			int filterStart = Math.min(indexOrEnd(name, '<'), indexOrEnd(name, '>'));
			String pattern = name.substring(0, filterStart).trim();
			if (!pattern.isEmpty())
			{
				groundItemsNames.add(pattern);
			}
		}

		Set<Integer> overlaps = new HashSet<>();
		for (int itemId : hiddenItemIds)
		{
			String itemName = getItemName(itemId).trim();
			if (!itemName.equalsIgnoreCase("Unknown item")
				&& groundItemsNames.stream().anyMatch(pattern -> matchesGroundItemsName(pattern, itemName)))
			{
				overlaps.add(itemId);
			}
		}
		return overlaps;
	}

	private static boolean matchesGroundItemsName(String pattern, String itemName)
	{
		return pattern.contains("*")
			? WildcardMatcher.matches(pattern, itemName)
			: pattern.equalsIgnoreCase(itemName);
	}

	private void refreshGroundItemsPluginHiddenItemIds()
	{
		if (!hideGroundItemsPluginItems || !isGroundItemsPluginActive())
		{
			groundItemsPluginHiddenItemIds = Collections.emptySet();
			return;
		}

		try
		{
			String configuredItems = configManager.getConfiguration("grounditems", "hiddenItems", String.class);
			if (configuredItems == null)
			{
				groundItemsPluginHiddenItemIds = Collections.emptySet();
				return;
			}

			Set<String> patterns = new HashSet<>();
			for (String value : Text.fromCSV(configuredItems))
			{
				String name = value.trim();
				int filterStart = Math.min(indexOrEnd(name, '<'), indexOrEnd(name, '>'));
				String pattern = name.substring(0, filterStart).trim();
				if (!pattern.isEmpty())
				{
					patterns.add(pattern);
				}
			}

			Set<Integer> matchingIds = new HashSet<>();
			for (int itemId = 0; itemId < client.getItemCount(); itemId++)
			{
				String itemName = itemManager.getItemComposition(itemId).getName();
				if (itemName != null && patterns.stream().anyMatch(pattern -> matchesGroundItemsName(pattern, itemName)))
				{
					matchingIds.add(itemId);
				}
			}
			groundItemsPluginHiddenItemIds = Collections.unmodifiableSet(matchingIds);
		}
		catch (RuntimeException ex)
		{
			groundItemsPluginHiddenItemIds = Collections.emptySet();
			log.debug("Unable to read the Ground Items hidden-item list; integration disabled for this refresh", ex);
		}
		panel.refresh();
	}

	boolean isGroundItemsPluginActive()
	{
		for (Plugin plugin : pluginManager.getPlugins())
		{
			if (plugin instanceof GroundItemsPlugin)
			{
				return pluginManager.isPluginActive(plugin);
			}
		}
		return false;
	}

	private static int indexOrEnd(String value, char character)
	{
		int index = value.indexOf(character);
		return index == -1 ? value.length() : index;
	}

	String getItemName(int itemId)
	{
		return itemNames.getOrDefault(itemId, "Unknown item");
	}

	void resolveItemNames()
	{
		resolveItemNames(hiddenItemIds);
	}

	void resolveItemNames(Collection<Integer> ids)
	{
		Set<Integer> idsToResolve = new HashSet<>(ids);
		clientThread.invoke(() ->
		{
			for (int itemId : idsToResolve)
			{
				rememberItemName(itemId);
			}
			panel.refresh();
			panel.refreshPopularSearchResults();
		});
	}

	private void rememberItemName(int itemId)
	{
		itemNames.putIfAbsent(itemId, itemManager.getItemComposition(itemId).getName());
	}

	private void setHiddenItemIds(Set<Integer> ids)
	{
		globalHiddenItemIds = Collections.unmodifiableSet(new HashSet<>(ids));
		// This pending value represents only the persisted global list. The effective
		// runtime set also contains active profile IDs and must never be loaded back
		// into the global list during a state refresh.
		pendingHiddenItemIds = globalHiddenItemIds;
		persistGlobalHiddenItemIds(globalHiddenItemIds);
		rebuildEffectiveHiddenItems();
	}

	private void rebuildEffectiveHiddenItems()
	{
		Set<Integer> effectiveIds = new HashSet<>(globalHiddenItemIds);
		effectiveIds.addAll(activeProfileItemIds);
		Set<Integer> updatedIds = Collections.unmodifiableSet(effectiveIds);
		hiddenItemIds = updatedIds;
		resolveItemNames();
		panel.refresh();
	}

	private void rebuildActiveProfileCache()
	{
		Set<Integer> itemIds = new HashSet<>();
		List<ActiveProfileData> profiles = new ArrayList<>();
		Set<String> validNames = new LinkedHashSet<>();
		for (String profileName : activeProfileNames)
		{
			Set<Integer> ids = savedProfiles.get(profileName);
			if (ids == null)
			{
				continue;
			}

			validNames.add(profileName);
			Set<Integer> regionIds = savedProfileRegions.containsKey(profileName)
				? savedProfileRegions.get(profileName)
				: Collections.emptySet();
			ProfileBoundary boundary = copyBoundary(savedProfileBoundaries.get(profileName));
			profiles.add(new ActiveProfileData(profileName, ids, regionIds, boundary));
			itemIds.addAll(ids);
		}

		activeProfileNames = Collections.unmodifiableSet(validNames);
		activeProfileItemIds = Collections.unmodifiableSet(itemIds);
		activeProfiles = Collections.unmodifiableList(profiles);
	}

	private void persistGlobalHiddenItemIds(Set<Integer> ids)
	{
		String value = serializeHiddenItemIds(ids);
		setHiddenItemIdsConfiguration(value, configManager.getRSProfileKey());
	}

	private void persistActiveProfiles(Collection<String> profileNames)
	{
		String profileKey = configManager.getRSProfileKey();
		if (profileKey == null)
		{
			return;
		}

		synchronized (this)
		{
			configWrite = configWrite.handle((ignored, error) -> null)
				.thenRunAsync(() ->
				{
					if (profileNames.isEmpty())
					{
						configManager.unsetConfiguration(
							HideGroundItemsConfig.GROUP, profileKey, ACTIVE_PROFILE_CONFIG_KEY);
					}
					else
					{
						configManager.setConfiguration(
							HideGroundItemsConfig.GROUP, profileKey, ACTIVE_PROFILE_CONFIG_KEY,
							gson.toJson(profileNames));
					}
				}, executor);
		}
	}

	private static String serializeHiddenItemIds(Set<Integer> ids)
	{
		Set<String> values = new java.util.TreeSet<>();
		ids.forEach(id -> values.add(String.valueOf(id)));
		return Text.toCSV(values);
	}

	private void setConfiguration(String key, Object value)
	{
		synchronized (this)
		{
			configWrite = configWrite.handle((ignored, error) -> null)
				.thenRunAsync(() ->
				{
					configManager.setConfiguration(HideGroundItemsConfig.GROUP, key, value);
				}, executor);
		}
	}

	private void setHiddenItemIdsConfiguration(String value, String profileKey)
	{
		synchronized (this)
		{
			configWrite = configWrite.handle((ignored, error) -> null)
				.thenRunAsync(() ->
				{
					if (profileKey == null)
					{
						// Search can be used before login; retain a temporary global value
						// until a RuneScape profile becomes available.
						configManager.setConfiguration(HideGroundItemsConfig.GROUP, HIDDEN_ITEM_IDS_CONFIG_KEY, value);
					}
					else
					{
						configManager.setConfiguration(
							HideGroundItemsConfig.GROUP, profileKey, HIDDEN_ITEM_IDS_CONFIG_KEY, value);
					}
				}, executor);
		}
	}

	private void setSavedProfiles(Map<String, Set<Integer>> profiles, Map<String, Set<Integer>> regions,
		Map<String, ProfileBoundary> boundaries)
	{
		Map<String, Set<Integer>> copy = new LinkedHashMap<>();
		for (Map.Entry<String, Set<Integer>> entry : profiles.entrySet())
		{
			copy.put(entry.getKey(), Collections.unmodifiableSet(new HashSet<>(entry.getValue())));
		}
		savedProfiles = Collections.unmodifiableMap(copy);
		Map<String, Set<Integer>> regionCopy = new LinkedHashMap<>();
		for (Map.Entry<String, Set<Integer>> entry : regions.entrySet())
		{
			if (copy.containsKey(entry.getKey()))
			{
				regionCopy.put(entry.getKey(), Collections.unmodifiableSet(new HashSet<>(entry.getValue())));
			}
		}
		savedProfileRegions = Collections.unmodifiableMap(regionCopy);
		Map<String, ProfileBoundary> boundaryCopy = new LinkedHashMap<>();
		for (Map.Entry<String, ProfileBoundary> entry : boundaries.entrySet())
		{
			if (copy.containsKey(entry.getKey()))
			{
				boundaryCopy.put(entry.getKey(), copyBoundary(entry.getValue()));
			}
		}
		savedProfileBoundaries = Collections.unmodifiableMap(boundaryCopy);
		rebuildActiveProfileCache();
		rebuildEffectiveHiddenItems();
		savedProfilesLoaded = true;
		panel.refresh();

		String value = gson.toJson(copy);
		String regionValue = gson.toJson(regionCopy);
		String boundaryValue = gson.toJson(boundaryCopy);
		String profileKey = configManager.getRSProfileKey();
		if (profileKey == null)
		{
			return;
		}

		synchronized (this)
		{
			configWrite = configWrite.handle((ignored, error) -> null)
				.thenRunAsync(() ->
				{
					configManager.setConfiguration(
						HideGroundItemsConfig.GROUP, profileKey, SAVED_PROFILES_CONFIG_KEY, value);
					configManager.setConfiguration(
						HideGroundItemsConfig.GROUP, profileKey, SAVED_PROFILE_REGIONS_CONFIG_KEY, regionValue);
					configManager.setConfiguration(
						HideGroundItemsConfig.GROUP, profileKey, SAVED_PROFILE_BOUNDARIES_CONFIG_KEY, boundaryValue);
				}, executor);
		}
	}

	private void loadSavedProfiles()
	{
		String value = configManager.getRSProfileConfiguration(
			HideGroundItemsConfig.GROUP, SAVED_PROFILES_CONFIG_KEY);
		if (value == null || value.trim().isEmpty())
		{
			savedProfiles = Collections.emptyMap();
			savedProfileBoundaries = Collections.emptyMap();
			savedProfilesLoaded = true;
			return;
		}

		try
		{
			Map<String, List<Integer>> decoded = gson.fromJson(value,
				new TypeToken<Map<String, List<Integer>>>() { }.getType());
			Map<String, Set<Integer>> profiles = new LinkedHashMap<>();
			if (decoded != null)
			{
				for (Map.Entry<String, List<Integer>> entry : decoded.entrySet())
				{
					String name = normalizeProfileName(entry.getKey());
					if (name != null && entry.getValue() != null)
					{
						profiles.put(name, Collections.unmodifiableSet(new HashSet<>(entry.getValue())));
					}
				}
			}
			savedProfiles = Collections.unmodifiableMap(profiles);
			loadSavedProfileRegions();
			loadSavedProfileBoundaries();
		}
		catch (RuntimeException ex)
		{
			savedProfiles = Collections.emptyMap();
			log.warn("Unable to load saved Hide Ground Items profiles", ex);
		}
		savedProfilesLoaded = true;
	}

	private void loadSavedProfileRegions()
	{
		String value = configManager.getRSProfileConfiguration(
			HideGroundItemsConfig.GROUP, SAVED_PROFILE_REGIONS_CONFIG_KEY);
		if (value == null || value.trim().isEmpty())
		{
			savedProfileRegions = Collections.emptyMap();
			return;
		}

		try
		{
			Map<String, List<Integer>> decoded = gson.fromJson(value,
				new TypeToken<Map<String, List<Integer>>>() { }.getType());
			Map<String, Set<Integer>> regions = new LinkedHashMap<>();
			if (decoded != null)
			{
				for (Map.Entry<String, List<Integer>> entry : decoded.entrySet())
				{
					String name = normalizeProfileName(entry.getKey());
					if (name != null && savedProfiles.containsKey(name) && entry.getValue() != null)
					{
						regions.put(name, normalizeRegionIds(entry.getValue()));
					}
				}
			}
			savedProfileRegions = Collections.unmodifiableMap(regions);
		}
		catch (RuntimeException ex)
		{
			savedProfileRegions = Collections.emptyMap();
			log.warn("Unable to load saved Hide Ground Items profile regions", ex);
		}
	}

	private void loadSavedProfileBoundaries()
	{
		String value = configManager.getRSProfileConfiguration(
			HideGroundItemsConfig.GROUP, SAVED_PROFILE_BOUNDARIES_CONFIG_KEY);
		if (value == null || value.trim().isEmpty())
		{
			savedProfileBoundaries = Collections.emptyMap();
			return;
		}

		try
		{
			Map<String, ProfileBoundary> decoded = gson.fromJson(value,
				new TypeToken<Map<String, ProfileBoundary>>() { }.getType());
			Map<String, ProfileBoundary> boundaries = new LinkedHashMap<>();
			if (decoded != null)
			{
				for (Map.Entry<String, ProfileBoundary> entry : decoded.entrySet())
				{
					String name = normalizeProfileName(entry.getKey());
					if (name != null && savedProfiles.containsKey(name))
					{
						boundaries.put(name, copyBoundary(entry.getValue()));
					}
				}
			}
			savedProfileBoundaries = Collections.unmodifiableMap(boundaries);
		}
		catch (RuntimeException ex)
		{
			savedProfileBoundaries = Collections.emptyMap();
			log.warn("Unable to load saved Hide Ground Items profile boundaries", ex);
		}
	}

	private void loadActiveProfile()
	{
		String configured = configManager.getRSProfileConfiguration(
			HideGroundItemsConfig.GROUP, ACTIVE_PROFILE_CONFIG_KEY);
		Set<String> names = new LinkedHashSet<>();
		if (configured != null && !configured.trim().isEmpty())
		{
			try
			{
				if (configured.trim().startsWith("["))
				{
					List<String> decoded = gson.fromJson(configured,
						new TypeToken<List<String>>() { }.getType());
					if (decoded != null)
					{
						for (String name : decoded)
						{
							String normalized = normalizeProfileName(name);
							if (normalized != null && savedProfiles.containsKey(normalized))
							{
								names.add(normalized);
							}
						}
					}
				}
				else
				{
					String normalized = normalizeProfileName(configured);
					if (normalized != null && savedProfiles.containsKey(normalized))
					{
						names.add(normalized);
					}
				}
			}
			catch (RuntimeException ex)
			{
				log.debug("Unable to load active Hide Ground Items profiles", ex);
			}
		}
		activeProfileNames = Collections.unmodifiableSet(names);
		rebuildActiveProfileCache();
		rebuildEffectiveHiddenItems();
	}

	private static Set<Integer> normalizeRegionIds(Collection<Integer> regionIds)
	{
		Set<Integer> normalized = new java.util.TreeSet<>();
		if (regionIds != null)
		{
			for (Integer regionId : regionIds)
			{
				if (regionId != null && regionId >= 0)
				{
					normalized.add(regionId);
				}
			}
		}
		return normalized;
	}

	private static String normalizeProfileName(String profileName)
	{
		if (profileName == null)
		{
			return null;
		}

		String normalized = profileName.trim();
		return normalized.isEmpty() ? null : normalized.substring(0, Math.min(normalized.length(), 32));
	}

	private void updateState()
	{
		Boolean configuredHideAll = configManager.getConfiguration(HideGroundItemsConfig.GROUP, "hideAll", Boolean.class);
		Boolean configuredHideListedItems = configManager.getConfiguration(HideGroundItemsConfig.GROUP, "hideListedItems", Boolean.class);
		String legacyConfiguredItemIds = configManager.getConfiguration(
			HideGroundItemsConfig.GROUP, HIDDEN_ITEM_IDS_CONFIG_KEY, String.class);
		String configuredItemIds = configManager.getRSProfileConfiguration(
			HideGroundItemsConfig.GROUP, HIDDEN_ITEM_IDS_CONFIG_KEY);
		hideAll = configuredHideAll != null && configuredHideAll;
		hideListedItems = configuredHideListedItems == null || configuredHideListedItems;
		Boolean configuredHideGroundItemLabels = configManager.getConfiguration(
			HideGroundItemsConfig.GROUP, "hideGroundItemLabels", Boolean.class);
		if (configuredHideGroundItemLabels != null)
		{
			hideGroundItemLabels = configuredHideGroundItemLabels;
		}
		else
		{
			hideGroundItemLabels = false;
		}
		Boolean configuredHideGroundItemsPluginItems = configManager.getConfiguration(
			HideGroundItemsConfig.GROUP, "hideGroundItemsPluginItems", Boolean.class);
		hideGroundItemsPluginItems = configuredHideGroundItemsPluginItems != null && configuredHideGroundItemsPluginItems;
		Boolean configuredGroupItemsByName = configManager.getConfiguration(
			HideGroundItemsConfig.GROUP, "groupItemsByName", Boolean.class);
		groupItemsByName = configuredGroupItemsByName == null || configuredGroupItemsByName;
		Boolean configuredRemoveHiddenItemsFromSearch = configManager.getConfiguration(
			HideGroundItemsConfig.GROUP, "removeHiddenItemsFromSearch", Boolean.class);
		removeHiddenItemsFromSearch = configuredRemoveHiddenItemsFromSearch == null || configuredRemoveHiddenItemsFromSearch;
		if (!savedProfilesLoaded && configManager.getRSProfileKey() != null)
		{
			loadSavedProfiles();
			loadActiveProfile();
		}
		if (!hiddenItemIdsLoaded)
		{
			if (configuredItemIds == null)
			{
				configuredItemIds = legacyConfiguredItemIds;
				if (configuredItemIds != null && configManager.getRSProfileKey() != null)
				{
					configManager.setRSProfileConfiguration(
						HideGroundItemsConfig.GROUP, HIDDEN_ITEM_IDS_CONFIG_KEY, configuredItemIds);
					configManager.unsetConfiguration(HideGroundItemsConfig.GROUP, HIDDEN_ITEM_IDS_CONFIG_KEY);
				}
			}

			Set<Integer> ids = new HashSet<>();
			for (String value : Text.fromCSV(configuredItemIds == null ? "" : configuredItemIds))
			{
				try
				{
					ids.add(Integer.parseInt(value.trim()));
				}
				catch (NumberFormatException ignored)
				{
					log.debug("Ignoring invalid hidden ground item ID: {}", value);
				}
			}
			Set<Integer> pendingIds = pendingHiddenItemIds;
			if (pendingIds != null)
			{
				ids = new HashSet<>(pendingIds);
			}
			globalHiddenItemIds = Collections.unmodifiableSet(ids);
			hiddenItemIdsLoaded = true;
			rebuildEffectiveHiddenItems();
			resolveItemNames();
		}
		clientThread.invoke(this::refreshGroundItemsPluginHiddenItemIds);
	}

	private void updateGroundItemLabels()
	{
		if (!isGroundItemsPluginActive())
		{
			return;
		}

		if (!hideGroundItemLabels)
		{
			restoreGroundItemLabelsForUser();
			return;
		}

		String current = configManager.getConfiguration("grounditems", "itemHighlightMode", String.class);
		if (!labelsOverridden)
		{
			originalItemHighlightMode = current;
			labelsOverridden = true;
		}

		if (!"NONE".equals(current))
		{
			configManager.setConfiguration("grounditems", "itemHighlightMode", "NONE");
		}
	}

	private void restoreGroundItemLabelsForUser()
	{
		if (!isGroundItemsPluginActive())
		{
			return;
		}

		restoreGroundItemLabels(true);
		if ("NONE".equals(configManager.getConfiguration("grounditems", "itemHighlightMode", String.class)))
		{
			configManager.setConfiguration("grounditems", "itemHighlightMode", "BOTH");
		}
	}

	private void restoreGroundItemLabels(boolean userRequested)
	{
		if (!labelsOverridden)
		{
			return;
		}

		String current = configManager.getConfiguration("grounditems", "itemHighlightMode", String.class);
		if ("NONE".equals(current))
		{
			String restored = originalItemHighlightMode;
			if (userRequested && (restored == null || "NONE".equals(restored)))
			{
				restored = "BOTH";
			}
			if (restored == null)
			{
				configManager.unsetConfiguration("grounditems", "itemHighlightMode");
			}
			else
			{
				configManager.setConfiguration("grounditems", "itemHighlightMode", restored);
			}
		}

		labelsOverridden = false;
		originalItemHighlightMode = null;
	}

	private boolean shouldDraw(Renderable renderable, boolean drawingUI)
	{
		return !(renderable instanceof TileItem && isHiddenForRender((TileItem) renderable));
	}

	private boolean isHiddenForRender(TileItem item)
	{
		return isHidden(item)
			|| (revealHiddenItemsHotkeyPressed && isHiddenIgnoringReveal(item));
	}

	static final class RevealItemHitbox
	{
		final java.awt.Rectangle bounds;
		final int itemId;
		final boolean remove;

		RevealItemHitbox(java.awt.Rectangle bounds, int itemId, boolean remove)
		{
			this.bounds = bounds;
			this.itemId = itemId;
			this.remove = remove;
		}
	}

	private BufferedImage createIcon()
	{
		try (InputStream stream = HideGroundItemsPlugin.class.getResourceAsStream("/hide_ground_items_icon.png"))
		{
			if (stream != null)
			{
				BufferedImage icon = ImageIO.read(stream);
				if (icon != null)
				{
					return icon;
				}
			}
		}
		catch (IOException ex)
		{
			log.warn("Unable to load the Hide Ground Items icon", ex);
		}

		// Keep plugin startup resilient if a packaged resource is ever missing.
		BufferedImage icon = new BufferedImage(16, 16, BufferedImage.TYPE_INT_ARGB);
		Graphics2D graphics = icon.createGraphics();
		graphics.setColor(new Color(60, 60, 60));
		graphics.fillRect(1, 1, 14, 14);
		graphics.setColor(new Color(220, 170, 70));
		graphics.fillRect(4, 4, 8, 8);
		graphics.setColor(Color.BLACK);
		graphics.drawRect(1, 1, 14, 14);
		graphics.dispose();
		return icon;
	}

