import java.awt.Polygon;
import java.awt.Rectangle;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import net.runelite.api.ItemLayer;
import net.runelite.api.Model;
import net.runelite.api.Perspective;
import net.runelite.api.TileItem;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.overlay.components.TextComponent;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayPosition;

final class HideGroundItemsModelOverlay extends Overlay
{
	private static final double DEFAULT_JAGEX_BRIGHTNESS = 0.8d;

	private final HideGroundItemsPlugin plugin;
	private final TextComponent textComponent = new TextComponent();

	@Inject
	HideGroundItemsModelOverlay(HideGroundItemsPlugin plugin)
	{
		this.plugin = plugin;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(net.runelite.client.ui.overlay.OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		renderBoundarySelection(graphics);
		Set<TileItem> items = plugin.getTrackedGroundItems();
		for (TileItem item : items)
		{
			boolean hiddenIgnoringReveal = plugin.isHiddenIgnoringReveal(item);
			if (plugin.isHidden(item))
			{
				continue;
			}

			ItemLayer layer = plugin.getItemLayer(item);
			if (layer == null || !plugin.layerHasHiddenItem(layer))
			{
				continue;
			}

			Model model = item.getModel();
			if (model == null)
			{
				continue;
			}

			if (hiddenIgnoringReveal && plugin.isRevealHiddenItemsHotkeyPressed())
			{
				continue;
			}
			else
			{
				drawModel(graphics, model, layer);
			}
		}
		if (plugin.isRevealHiddenItemsHotkeyPressed())
		{
			renderRevealLabels(graphics);
		}
		else
		{
			plugin.clearRevealItemHitboxes();
		}
		return null;
	}

	private void renderRevealLabels(Graphics2D graphics)
	{
		List<HideGroundItemsPlugin.RevealItemHitbox> hitboxes = new ArrayList<>();
		Map<WorldPoint, Integer> offsets = new HashMap<>();
		FontMetrics fontMetrics = graphics.getFontMetrics();
		net.runelite.api.Point mousePosition = plugin.getClient().getMouseCanvasPosition();

		for (TileItem item : plugin.getTrackedGroundItems())
		{
			ItemLayer layer = plugin.getItemLayer(item);
			if (layer == null)
			{
				continue;
			}

			LocalPoint localLocation = layer.getLocalLocation();
			WorldPoint worldLocation = layer.getWorldLocation();
			if (localLocation == null || worldLocation == null)
			{
				continue;
			}

			String label = plugin.getGroundItemDisplayName(item);
			int offset = offsets.compute(worldLocation, (ignored, value) -> value == null ? 0 : value + 1);
			net.runelite.api.Point textPoint = Perspective.getCanvasTextLocation(
				plugin.getClient(), graphics, localLocation, label, layer.getHeight() + 20);
			if (textPoint == null)
			{
				continue;
			}

			int textX = textPoint.getX();
			int textY = textPoint.getY() - (15 * offset);
			int textWidth = fontMetrics.stringWidth(label);
			int textHeight = fontMetrics.getHeight();
			Rectangle textBounds = new Rectangle(textX - 2, textY - textHeight - 2,
				textWidth + 4, textHeight + 4);
			Rectangle actionBounds = new Rectangle(textBounds.x + textBounds.width + 2,
				textY - (8 + textHeight) / 2, 8, 8);
			boolean remove = plugin.isGlobalHiddenItem(item.getId());
			boolean hovered = mousePosition != null && actionBounds.contains(
				mousePosition.getX(), mousePosition.getY());

			if (hovered)
			{
				graphics.setColor(new Color(30, 30, 30, 220));
				graphics.fillRect(textBounds.x - 2, textBounds.y - 2,
					textBounds.width + actionBounds.width + 6, textBounds.height + 4);
			}

			textComponent.setText(label);
			textComponent.setPosition(textX, textY);
			textComponent.setColor(remove ? Color.GRAY : Color.WHITE);
			textComponent.setOutline(true);
			textComponent.render(graphics);
			drawActionBox(graphics, actionBounds, remove, hovered);
			hitboxes.add(new HideGroundItemsPlugin.RevealItemHitbox(actionBounds,
				item.getId(), remove));
		}

		plugin.setRevealItemHitboxes(hitboxes);
	}

	private static void drawActionBox(Graphics2D graphics, Rectangle bounds, boolean remove, boolean hovered)
	{
		graphics.setColor(Color.BLACK);
		graphics.drawRect(bounds.x + 1, bounds.y + 1, bounds.width, bounds.height);
		graphics.setColor(hovered ? Color.WHITE : (remove ? Color.RED : Color.GREEN));
		graphics.draw(bounds);
		if (remove)
		{
			graphics.fillRect(bounds.x + 2, bounds.y + 3, bounds.width - 3, 2);
		}
		else
		{
			graphics.drawLine(bounds.x + 2, bounds.y + bounds.height / 2,
				bounds.x + bounds.width - 2, bounds.y + bounds.height / 2);
			graphics.drawLine(bounds.x + bounds.width / 2, bounds.y + 2,
				bounds.x + bounds.width / 2, bounds.y + bounds.height - 2);
		}
	}

	private void renderBoundarySelection(Graphics2D graphics)
	{
		boolean selecting = plugin.isBoundarySelectionActive();
		if (!selecting && !plugin.isProfileEditing())
		{
			return;
		}

		Composite oldComposite = graphics.getComposite();
		graphics.setComposite(java.awt.AlphaComposite.getInstance(java.awt.AlphaComposite.SRC_OVER, 0.45f));
		graphics.setColor(new Color(255, 210, 40, 130));
		Set<HideGroundItemsPlugin.TileCoordinate> previewTiles = selecting
			? plugin.getBoundarySelectionPreviewTiles()
			: plugin.getProfileDraftBoundaryPreviewTiles();
		for (HideGroundItemsPlugin.TileCoordinate tile : previewTiles)
		{
			drawTile(graphics, tile, false);
		}

		graphics.setComposite(java.awt.AlphaComposite.getInstance(java.awt.AlphaComposite.SRC_OVER, 0.95f));
		graphics.setColor(new Color(255, 225, 60));
		if (selecting)
		{
			java.util.List<HideGroundItemsPlugin.TileCoordinate> vertices = plugin.getBoundarySelectionVertices();
			for (HideGroundItemsPlugin.TileCoordinate vertex : vertices)
			{
				drawTile(graphics, vertex, true);
			}
			for (int index = 1; index < vertices.size(); index++)
			{
				drawBoundaryLine(graphics, vertices.get(index - 1), vertices.get(index));
			}
		}
		else
		{
			for (java.util.List<HideGroundItemsPlugin.TileCoordinate> polygon
				: plugin.getProfileDraftBoundary().polygons)
			{
				for (int index = 1; index < polygon.size(); index++)
				{
					drawBoundaryLine(graphics, polygon.get(index - 1), polygon.get(index));
				}
				if (polygon.size() >= 3)
				{
					drawBoundaryLine(graphics, polygon.get(polygon.size() - 1), polygon.get(0));
				}
			}
		}
		HideGroundItemsPlugin.TileCoordinate hovered = selecting ? plugin.getHoveredBoundaryTile() : null;
		if (hovered != null)
		{
			graphics.setColor(new Color(255, 245, 140));
			Polygon tilePolygon = getCanvasTilePolygon(hovered);
			if (tilePolygon != null)
			{
				graphics.drawPolygon(tilePolygon);
			}

			// Show the next polygon edge before the click. Besides making the
			// drawing interaction clearer, this gives immediate feedback about
			// which tile RuneLite resolved beneath the cursor.
			java.util.List<HideGroundItemsPlugin.TileCoordinate> vertices = plugin.getBoundarySelectionVertices();
			if (selecting && !vertices.isEmpty() && !hovered.equals(vertices.get(vertices.size() - 1)))
			{
				graphics.setColor(new Color(255, 245, 140, 220));
				drawBoundaryLine(graphics, vertices.get(vertices.size() - 1), hovered);
			}
		}

		graphics.setComposite(oldComposite);
		if (!selecting)
		{
			return;
		}

		int x = plugin.getClient().getViewportXOffset() + 10;
		int y = plugin.getClient().getViewportYOffset() + 52;
		String[] instructionLines = {
			plugin.isBoundaryPolygonMode()
				? "LEFT-CLICK tiles | ENTER finish | ESC cancel"
				: "LEFT-CLICK Tiles | SHIFT-CLICK rectangle | ENTER finish | ESC cancel"
		};
		int textWidth = 0;
		for (String line : instructionLines)
		{
			textWidth = Math.max(textWidth, graphics.getFontMetrics().stringWidth(line));
		}
		int boxWidth = textWidth + 12;
		int boxHeight = instructionLines.length * 15 + 8;
		graphics.setColor(new Color(30, 30, 30, 220));
		graphics.fillRoundRect(x - 6, y - 16, boxWidth, boxHeight, 6, 6);
		graphics.setColor(new Color(255, 225, 60));
		for (int index = 0; index < instructionLines.length; index++)
		{
			graphics.drawString(instructionLines[index], x, y + index * 15);
		}
	}

	private void drawBoundaryLine(Graphics2D graphics, HideGroundItemsPlugin.TileCoordinate first,
		HideGroundItemsPlugin.TileCoordinate second)
	{
		Polygon firstPolygon = getCanvasTilePolygon(first);
		Polygon secondPolygon = getCanvasTilePolygon(second);
		if (firstPolygon != null && secondPolygon != null)
		{
			graphics.drawLine(firstPolygon.getBounds().x + firstPolygon.getBounds().width / 2,
				firstPolygon.getBounds().y + firstPolygon.getBounds().height / 2,
				secondPolygon.getBounds().x + secondPolygon.getBounds().width / 2,
				secondPolygon.getBounds().y + secondPolygon.getBounds().height / 2);
		}
	}

	private void drawTile(Graphics2D graphics, HideGroundItemsPlugin.TileCoordinate tile, boolean outlineOnly)
	{
		Polygon polygon = getCanvasTilePolygon(tile);
		if (polygon == null)
		{
			return;
		}
		if (outlineOnly)
		{
			graphics.drawPolygon(polygon);
		}
		else
		{
			graphics.fillPolygon(polygon);
			graphics.drawPolygon(polygon);
		}
	}

	private Polygon getCanvasTilePolygon(HideGroundItemsPlugin.TileCoordinate tile)
	{
		if (tile == null || plugin.getClient().getTopLevelWorldView() == null)
		{
			return null;
		}

		WorldPoint worldPoint = new WorldPoint(tile.x, tile.y, tile.plane);
		net.runelite.api.WorldView worldView = plugin.getClient().getTopLevelWorldView();
		if (worldView.getInstanceTemplateChunks() == null
			&& !WorldPoint.isInScene(worldView, worldPoint.getX(), worldPoint.getY()))
		{
			return null;
		}

		for (WorldPoint localPoint : WorldPoint.toLocalInstance(worldView, worldPoint))
		{
			LocalPoint localLocation = LocalPoint.fromWorld(
				worldView, localPoint.getX(), localPoint.getY());
			if (localLocation != null)
			{
				Polygon polygon = Perspective.getCanvasTilePoly(plugin.getClient(), localLocation);
				if (polygon != null)
				{
					return polygon;
				}
			}
		}
		return null;
	}

	private void drawModel(Graphics2D graphics, Model model, ItemLayer layer)
	{
		int vertexCount = model.getVerticesCount();
		float[] verticesX = model.getVerticesX();
		float[] verticesY = model.getVerticesY();
		float[] verticesZ = model.getVerticesZ();
		int[] screenX = new int[vertexCount];
		int[] screenY = new int[vertexCount];

		Perspective.modelToCanvas(plugin.getClient(), layer.getWorldView(), vertexCount,
			layer.getX(), layer.getY(), layer.getZ() - layer.getHeight(), 0,
			verticesX, verticesZ, verticesY, screenX, screenY);

		int[] indices1 = model.getFaceIndices1();
		int[] indices2 = model.getFaceIndices2();
		int[] indices3 = model.getFaceIndices3();
		int[] colors1 = model.getFaceColors1();
		int[] colors2 = model.getFaceColors2();
		int[] colors3 = model.getFaceColors3();
		short[] faceTextures = model.getFaceTextures();
		int[] faceOrder = sortFacesBackToFront(model, layer, vertexCount, indices1, indices2, indices3);
		net.runelite.api.TextureProvider textureProvider = plugin.getClient().getTextureProvider();
		double brightness = textureProvider == null ? DEFAULT_JAGEX_BRIGHTNESS : textureProvider.getBrightness();
		for (int order = 0; order < faceOrder.length; order++)
		{
			int face = faceOrder[order];
			int color1 = colors1[face];
			int color2 = colors2[face];
			int color3 = colors3[face];
			if (color3 == -2)
			{
				continue;
			}
			if (color3 == -1)
			{
				color2 = color3 = color1;
			}
			if (faceTextures == null || faceTextures[face] == -1)
			{
				color1 = applyModelOverride(color1, model);
				color2 = applyModelOverride(color2, model);
				color3 = applyModelOverride(color3, model);
			}

			int a = indices1[face];
			int b = indices2[face];
			int c = indices3[face];
			if (!validPoint(screenX[a], screenY[a]) || !validPoint(screenX[b], screenY[b])
				|| !validPoint(screenX[c], screenY[c]))
			{
				continue;
			}

			graphics.setColor(averageColor(color1, color2, color3, brightness));
			graphics.fillPolygon(new Polygon(
				new int[]{screenX[a], screenX[b], screenX[c]},
				new int[]{screenY[a], screenY[b], screenY[c]}, 3));
		}
	}

	private int[] sortFacesBackToFront(Model model, ItemLayer layer, int vertexCount,
		int[] indices1, int[] indices2, int[] indices3)
	{
		float[] depths = new float[vertexCount];
		float pitch;
		float yaw;
		float cameraX;
		float cameraY;
		float cameraZ;
		if (plugin.getClient().isGpu())
		{
			pitch = plugin.getClient().getCameraFpPitch();
			yaw = plugin.getClient().getCameraFpYaw();
			cameraX = plugin.getClient().getCameraFpX();
			cameraY = plugin.getClient().getCameraFpY();
			cameraZ = plugin.getClient().getCameraFpZ();
		}
		else
		{
			pitch = plugin.getClient().getCameraPitch() * (float) Math.PI / 1024f;
			yaw = plugin.getClient().getCameraYaw() * (float) Math.PI / 1024f;
			cameraX = plugin.getClient().getCameraX();
			cameraY = plugin.getClient().getCameraY();
			cameraZ = plugin.getClient().getCameraZ();
		}

		float pitchSin = (float) Math.sin(pitch);
		float pitchCos = (float) Math.cos(pitch);
		float yawSin = (float) Math.sin(yaw);
		float yawCos = (float) Math.cos(yaw);
		float centerX = layer.getX() - cameraX;
		float centerY = layer.getY() - cameraY;
		float centerZ = layer.getZ() - layer.getHeight() - cameraZ;
		float[] verticesX = model.getVerticesX();
		float[] verticesY = model.getVerticesY();
		float[] verticesZ = model.getVerticesZ();
		for (int vertex = 0; vertex < vertexCount; vertex++)
		{
			float x = verticesX[vertex] + centerX;
			float y = verticesY[vertex] + centerY;
			float z = verticesZ[vertex] + centerZ;
			float cameraY1 = y * yawCos - x * yawSin;
			depths[vertex] = cameraY1 * pitchCos + z * pitchSin;
		}

		int faceCount = model.getFaceCount();
		int[] faceOrder = new int[faceCount];
		float[] faceDepths = new float[faceCount];
		for (int face = 0; face < faceCount; face++)
		{
			faceOrder[face] = face;
			faceDepths[face] = (depths[indices1[face]] + depths[indices2[face]] + depths[indices3[face]]) / 3f;
		}

		for (int index = 1; index < faceCount; index++)
		{
			int face = faceOrder[index];
			float depth = faceDepths[face];
			int position = index - 1;
			while (position >= 0 && faceDepths[faceOrder[position]] < depth)
			{
				faceOrder[position + 1] = faceOrder[position];
				position--;
			}
			faceOrder[position + 1] = face;
		}
		return faceOrder;
	}

	private static int applyModelOverride(int hsl, Model model)
	{
		int amount = model.getOverrideAmount() & 0xff;
		if (amount == 0)
		{
			return hsl;
		}

		int hue = hsl >> 10 & 63;
		int saturation = hsl >> 7 & 7;
		int lightness = hsl & 127;
		int overrideHue = model.getOverrideHue();
		int overrideSaturation = model.getOverrideSaturation();
		int overrideLightness = model.getOverrideLuminance();
		if (overrideHue != -1)
		{
			hue += amount * (overrideHue - hue) >> 7;
		}
		if (overrideSaturation != -1)
		{
			saturation += amount * (overrideSaturation - saturation) >> 7;
		}
		if (overrideLightness != -1)
		{
			lightness += amount * (overrideLightness - lightness) >> 7;
		}
		return (hue << 10 | saturation << 7 | lightness) & 0xffff;
	}

	private static boolean validPoint(int x, int y)
	{
		return x != Integer.MIN_VALUE && y != Integer.MIN_VALUE;
	}

	private static Color averageColor(int value1, int value2, int value3, double brightness)
	{
		Color color1 = hslToColor(value1, brightness);
		Color color2 = hslToColor(value2, brightness);
		Color color3 = hslToColor(value3, brightness);
		return new Color((color1.getRed() + color2.getRed() + color3.getRed()) / 3,
			(color1.getGreen() + color2.getGreen() + color3.getGreen()) / 3,
			(color1.getBlue() + color2.getBlue() + color3.getBlue()) / 3);
	}

	private static Color hslToColor(int value, double brightness)
	{
		double hue = ((value >> 10) & 63) / 64d + 0.5d / 64d;
		double saturation = ((value >> 7) & 7) / 8d + 0.5d / 8d;
		double lightness = (value & 127) / 128d;
		double chroma = (1d - Math.abs(2d * lightness - 1d)) * saturation;
		double scaledHue = hue * 6d;
		double x = chroma * (1d - Math.abs(scaledHue % 2d - 1d));
		double red = lightness - chroma / 2d;
		double green = red;
		double blue = red;
		switch ((int) scaledHue)
		{
			case 0:
				red += chroma;
				green += x;
				break;
			case 1:
				green += chroma;
				red += x;
				break;
			case 2:
				green += chroma;
				blue += x;
				break;
			case 3:
				blue += chroma;
				green += x;
				break;
			case 4:
				blue += chroma;
				red += x;
				break;
			default:
				red += chroma;
				blue += x;
				break;
		}

		return new Color(
			adjustForBrightness(red, brightness),
			adjustForBrightness(green, brightness),
			adjustForBrightness(blue, brightness));
	}

	private static int adjustForBrightness(double channel, double brightness)
	{
		int value = (int) (Math.pow(clamp(channel), brightness) * 256d);
		return Math.max(0, Math.min(255, value));
	}

	private static double clamp(double value)
	{
		return Math.max(0d, Math.min(1d, value));
	}
}
